package com.codex.autopilot;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class CodexAutopilotPluginRunner
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(CodexAutopilotPlugin.class);
		RuneLite.main(args);
	}
}

package com.codex.autopilot;

import com.codex.autopilot.core.Budget;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup(CodexAutopilotConfig.GROUP)
public interface CodexAutopilotConfig extends Config
{
	String GROUP = "codexautopilot";

	@ConfigSection(name = "Display", description = "Where the next step shows", position = 0)
	String DISPLAY = "display";

	@ConfigSection(name = "Sources", description = "What Autopilot reads to find your next step", position = 1)
	String SOURCES = "sources";

	@ConfigSection(name = "Priorities", description = "How steps are put in order", position = 2)
	String PRIORITIES = "priorities";

	@ConfigSection(name = "Notifications", description = "Heads-up notifications through RuneLite's notifier", position = 3)
	String NOTIFICATIONS = "notifications";

	/** The time budget the panel's selector sets. */
	String BUDGET_KEY = "timeBudget";

	@ConfigItem(
		keyName = "plaque",
		name = "Show the plaque",
		description = "Show the next step on a plaque in the game view",
		section = DISPLAY,
		position = 0
	)
	default boolean plaque()
	{
		return true;
	}

	@ConfigItem(
		keyName = "quiet",
		name = "Quiet mode",
		description = "Only show steps about to go to waste: a daily before the reset, a diseased patch, the kingdom before its next drop",
		section = DISPLAY,
		position = 1
	)
	default boolean quiet()
	{
		return false;
	}

	@ConfigItem(
		keyName = "stepAside",
		name = "Step aside in minigames",
		description = "Hide the plaque in the Motherlode Mine, at the Blast Furnace and on Mahogany Homes contracts, where Codex Minigame Pilot guides",
		section = DISPLAY,
		position = 2
	)
	default boolean stepAside()
	{
		return true;
	}

	@ConfigItem(
		keyName = BUDGET_KEY,
		name = "Time budget",
		description = "Plan only what fits in this long: the panel and plaque show the best set of steps for the time, things going to waste first."
			+ " Also set from the top of the panel",
		section = DISPLAY,
		position = 3
	)
	default Budget timeBudget()
	{
		return Budget.NONE;
	}

	@ConfigItem(
		keyName = "chores",
		name = "Bird houses and patches",
		description = "Read bird houses, seaweed, special trees and special patches from RuneLite's Time Tracking plugin",
		section = SOURCES,
		position = 0
	)
	default boolean chores()
	{
		return true;
	}

	@ConfigItem(
		keyName = "herbs",
		name = "Herb runs",
		description = "Read herb patches from RuneLite's Time Tracking plugin, with the allotments and flower patches beside them",
		section = SOURCES,
		position = 1
	)
	default boolean herbs()
	{
		return true;
	}

	@ConfigItem(
		keyName = "hops",
		name = "Hops runs",
		description = "Read hops patches from RuneLite's Time Tracking plugin",
		section = SOURCES,
		position = 2
	)
	default boolean hops()
	{
		return true;
	}

	@ConfigItem(
		keyName = "dailies",
		name = "Diary dailies",
		description = "Battlestaves, essence, flax, sand and the other diary dailies, and finished farming contracts",
		section = SOURCES,
		position = 3
	)
	default boolean dailies()
	{
		return true;
	}

	@ConfigItem(
		keyName = "kingdom",
		name = "Kingdom of Miscellania",
		description = "Read approval and the coffer from RuneLite's Kingdom of Miscellania plugin",
		section = SOURCES,
		position = 4
	)
	default boolean kingdom()
	{
		return true;
	}

	@ConfigItem(
		keyName = "navigator",
		name = "Codex Navigator goals",
		description = "Add the next step toward the goals you pinned in Codex Navigator",
		section = SOURCES,
		position = 5
	)
	default boolean navigator()
	{
		return true;
	}

	@ConfigItem(
		keyName = "bankSteward",
		name = "Codex Bank Steward bank",
		description = "Check what a chore needs against the bank Codex Bank Steward last saw",
		section = SOURCES,
		position = 6
	)
	default boolean bankSteward()
	{
		return true;
	}

	@ConfigItem(
		keyName = "goalFirst",
		name = "Goal first",
		description = "Put your focused goal ahead of ready chores that lose little by waiting (trees, dailies with hours left, the kingdom)."
			+ " Anything about to go to waste and full bird houses still come first",
		section = PRIORITIES,
		position = 0
	)
	default boolean goalFirst()
	{
		return false;
	}

	@ConfigItem(
		keyName = "wasteHours",
		name = "Going to waste within (hours)",
		description = "How close a loss has to be before its step jumps to the front",
		section = PRIORITIES,
		position = 1
	)
	@Range(min = 1, max = 12)
	default int wasteHours()
	{
		return 3;
	}

	@ConfigItem(
		keyName = "approvalTarget",
		name = "Kingdom approval target",
		description = "Suggest a visit to Miscellania when approval falls below this",
		section = PRIORITIES,
		position = 2
	)
	@Range(max = 100)
	@Units(Units.PERCENT)
	default int approvalTarget()
	{
		return 90;
	}

	@ConfigItem(
		keyName = "cofferSlack",
		name = "Coffer short by",
		description = "Suggest topping up the coffer once it is this far below a full daily payout",
		section = PRIORITIES,
		position = 3
	)
	@Range(max = 7_500_000)
	default int cofferSlack()
	{
		return 150_000;
	}

	@ConfigItem(
		keyName = "learnPace",
		name = "Learn my pace",
		description = "Time your bird house, herb and other chore runs and show your own pace once three runs of a kind are timed."
			+ " Kept in this plugin's settings for the account; switch off to go back to the estimates",
		section = PRIORITIES,
		position = 4
	)
	default boolean learnPace()
	{
		return true;
	}

	@ConfigItem(
		keyName = "notify",
		name = "Notifications",
		description = "Send heads-up notifications through RuneLite's notifier, which has its own settings for when and how they show",
		section = NOTIFICATIONS,
		position = 0
	)
	default boolean notifications()
	{
		return true;
	}

	@ConfigItem(
		keyName = "notifyWaste",
		name = "Going to waste",
		description = "Notify once when something starts going to waste: a diseased patch, dailies before the reset, the kingdom",
		section = NOTIFICATIONS,
		position = 1
	)
	default boolean notifyWaste()
	{
		return true;
	}

	@ConfigItem(
		keyName = "notifyReady",
		name = "Chores ready",
		description = "Notify once when a chore trip becomes ready, such as full bird houses or a herb run",
		section = NOTIFICATIONS,
		position = 2
	)
	default boolean notifyReady()
	{
		return true;
	}
}

package com.codex.autopilot;

import com.codex.autopilot.core.Activity;
import com.codex.autopilot.core.Advisor;
import com.codex.autopilot.core.BankSnapshot;
import com.codex.autopilot.core.Budget;
import com.codex.autopilot.core.Candidate;
import com.codex.autopilot.core.Dailies;
import com.codex.autopilot.core.DailyState;
import com.codex.autopilot.core.Format;
import com.codex.autopilot.core.GoalBoard;
import com.codex.autopilot.core.Heads;
import com.codex.autopilot.core.Pace;
import com.codex.autopilot.core.PaceWatch;
import com.codex.autopilot.core.Plan;
import com.codex.autopilot.core.Profile;
import com.codex.autopilot.core.Ranker;
import com.codex.autopilot.core.Session;
import com.codex.autopilot.core.Settings;
import com.codex.autopilot.core.Tier;
import com.codex.autopilot.core.Vars;
import com.codex.autopilot.overlay.StepPlaque;
import com.codex.autopilot.ui.Actions;
import com.codex.autopilot.ui.AutopilotPanel;
import com.codex.autopilot.ui.Sigil;
import com.codex.autopilot.ui.View;
import com.google.gson.Gson;
import com.google.inject.Provides;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Objects;
import java.util.Set;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.client.Notifier;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;

/**
 * One next step for the whole account. Autopilot reads what RuneLite and the other Codex plugins
 * already know (Time Tracking's patches and bird houses, the Kingdom of Miscellania, the diary
 * dailies, Codex Navigator's goals and Codex Bank Steward's bank), ranks it all by what is lost
 * by waiting, and keeps the best step on a plaque and in its panel. It never clicks, changes
 * menus, writes another plugin's data or sends anything off the computer; the only things it
 * keeps are its own settings, among them the player's learned pace, and the only thing it sends
 * is a notification through RuneLite's own notifier.
 */
@PluginDescriptor(
	name = "Codex Autopilot",
	description = "One next step for your whole account: what is ready, what is about to go to waste and your pinned goal, in one order",
	tags = {"next", "step", "todo", "birdhouse", "farming", "daily", "kingdom", "miscellania", "goal", "navigator", "codex"}
)
public class CodexAutopilotPlugin extends Plugin
{
	/** Every few ticks the plan is worked out again, so countdowns move and new readings land. */
	private static final int EVALUATE_TICKS = 5;
	private static final int QUEST_TICKS = 100;
	/** How close a Mahogany Homes contractor has to be to count as being on a contract. */
	private static final int CONTRACTOR_RANGE = 12;
	/** The RuneLite config key that says whether Codex Minigame Pilot is switched on. */
	private static final String MINIGAME_PILOT_KEY = "codexminigamepilotplugin";
	/** The RuneLite config key that says whether Codex Rounds is switched on. */
	private static final String ROUNDS_KEY = "codexroundsplugin";
	/** Settings that make chore steps come or go: a run in progress is dropped rather than timed when one changes. */
	private static final Set<String> CHORE_KEYS = new HashSet<>(Arrays.asList("chores", "herbs", "hops", "learnPace"));
	private static final String TIME_TRACKING = "timetracking";

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ConfigManager configManager;

	@Inject
	private Gson gson;

	@Inject
	private CodexAutopilotConfig config;

	@Inject
	private Notifier notifier;

	private final StepPlaque plaque = new StepPlaque();
	private final Session session = new Session();
	private final Heads heads = new Heads();
	private final PaceWatch watch = new PaceWatch();

	private AutopilotPanel panel;
	private NavigationButton navButton;

	private int ticks;
	private volatile boolean skipped;
	private List<DailyState> dailies;
	private boolean royalTrouble;
	private Activity activity = Activity.NONE;

	// Parsed only when the saved text changes.
	private String boardJson;
	private GoalBoard board;
	private String bankJson;
	private BankSnapshot bank;
	private String paceJson;
	private Pace pace;

	@Provides
	CodexAutopilotConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(CodexAutopilotConfig.class);
	}

	@Override
	protected void startUp()
	{
		panel = new AutopilotPanel(new PanelActions());
		navButton = NavigationButton.builder()
			.tooltip("Codex Autopilot")
			.icon(Sigil.icon(16))
			.priority(6)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
		overlayManager.add(plaque);
		clientThread.invokeLater(() ->
		{
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				readLive(true);
			}
			evaluate();
		});
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(plaque);
		clientToolbar.removeNavigation(navButton);
		plaque.show(null);
		panel = null;
		session.clear();
		heads.reset();
		watch.abandon();
		skipped = false;
		dailies = null;
		activity = Activity.NONE;
		boardJson = null;
		board = null;
		bankJson = null;
		bank = null;
		paceJson = null;
		pace = null;
	}

	// ---- Events ----

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		ticks++;
		if (ticks % EVALUATE_TICKS != 0)
		{
			return;
		}
		readLive(ticks % QUEST_TICKS == 0);
		evaluate();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGIN_SCREEN || event.getGameState() == GameState.HOPPING)
		{
			dailies = null;
			activity = Activity.NONE;
			// Out of sight: a run in progress cannot be timed across it.
			watch.abandon();
			evaluate();
		}
		else if (event.getGameState() == GameState.LOGGED_IN)
		{
			ticks = 0;
			// What is already ready at login is old news: the first look after it only takes note.
			heads.reset();
			clientThread.invokeLater(() ->
			{
				readLive(true);
				evaluate();
			});
		}
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		// Another account: what was set aside, told or timed belonged to the last one.
		session.clear();
		heads.reset();
		watch.abandon();
		skipped = false;
		dailies = null;
		clientThread.invokeLater(() ->
		{
			// Its learned pace is read afresh, never carried over from the last account.
			pace = null;
			paceJson = null;
			evaluate();
		});
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		String group = event.getGroup();
		if (CodexAutopilotConfig.GROUP.equals(group) && CHORE_KEYS.contains(event.getKey()))
		{
			watch.abandon();
		}
		if (CodexAutopilotConfig.GROUP.equals(group) && Pace.KEY.equals(event.getKey()))
		{
			// Autopilot's own save of the pace; nothing new to show.
			return;
		}
		if (CodexAutopilotConfig.GROUP.equals(group) || TIME_TRACKING.equals(group) || GoalBoard.GROUP.equals(group)
			|| BankSnapshot.GROUP.equals(group) || "kingdomofmiscellania".equals(group))
		{
			clientThread.invokeLater(this::evaluate);
		}
	}

	// ---- Reading ----

	/** Reads what only the live game knows: the dailies, Royal Trouble and where the player is. On the client thread. */
	private void readLive(boolean quests)
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		Vars vars = new Vars()
		{
			@Override
			public int varbit(int id)
			{
				return client.getVarbitValue(id);
			}

			@Override
			public int varp(int id)
			{
				return client.getVarpValue(id);
			}
		};
		dailies = Dailies.read(vars);
		if (quests)
		{
			try
			{
				royalTrouble = Quest.ROYAL_TROUBLE.getState(client) == QuestState.FINISHED;
			}
			catch (RuntimeException e)
			{
				royalTrouble = false;
			}
		}
		activity = readActivity();
	}

	private Activity readActivity()
	{
		Player me = client.getLocalPlayer();
		if (me == null)
		{
			return Activity.NONE;
		}
		WorldPoint at = me.getWorldLocation();
		List<String> near = new ArrayList<>();
		for (NPC npc : client.getTopLevelWorldView().npcs())
		{
			if (npc != null && npc.getName() != null && npc.getWorldLocation().distanceTo(at) <= CONTRACTOR_RANGE)
			{
				near.add(npc.getName());
			}
		}
		return Activity.of(at.getRegionID(), near);
	}

	private Settings settings()
	{
		return Settings.defaults()
			.chores(config.chores())
			.herbs(config.herbs())
			.hops(config.hops())
			.rounds("true".equals(configManager.getConfiguration("runelite", ROUNDS_KEY)))
			.dailies(config.dailies())
			.kingdom(config.kingdom())
			.navigator(config.navigator())
			.bankSteward(config.bankSteward())
			.quiet(config.quiet())
			.goalFirst(config.goalFirst())
			.approvalTarget(config.approvalTarget())
			.cofferSlack(config.cofferSlack())
			.wasteHorizon(config.wasteHours() * 3600L);
	}

	/** Works the plan out again from everything read and hands it to the plaque and the panel. */
	private void evaluate()
	{
		long now = Instant.now().getEpochSecond();
		boolean known = configManager.getRSProfileKey() != null;
		boolean loggedIn = client.getGameState() == GameState.LOGGED_IN;
		Settings s = settings();
		Profile profile = (group, key) -> configManager.getRSProfileConfiguration(group, key);

		Advisor.Inputs in = new Advisor.Inputs();
		Plan plan = Plan.EMPTY;
		List<Candidate> all = new ArrayList<>();
		String nextUp = null;
		boolean learn = config.learnPace();
		if (known)
		{
			in = Advisor.Inputs.read(new OnlyCore(profile), gson, now, royalTrouble);
			in.board = board(profile);
			in.bank = bank(profile);
			in.pace = learn ? pace(profile) : null;
			in.dailies = loggedIn ? dailies : null;
			all = Advisor.candidates(in, s, now);
			plan = Ranker.rank(all, s, session, now);
			nextUp = Advisor.nextUp(in, s, now);
		}

		Budget budget = config.timeBudget() == null ? Budget.NONE : config.timeBudget();
		Budget.Fit fit = Budget.fit(plan, budget.getMinutes(), session);
		Candidate top = budget == Budget.NONE || fit.isEmpty() ? plan.top() : fit.first();

		if (known && loggedIn)
		{
			learn(all, top, now, learn);
			announce(all, plan, now);
		}

		boolean aside = config.stepAside() && activity != Activity.NONE;
		plaque.show(config.plaque() && loggedIn && !aside ? top : null);

		AutopilotPanel p = panel;
		if (p == null)
		{
			return;
		}
		View view = new View(loggedIn, known, plan, config.stepAside() ? activity : Activity.NONE,
			"true".equals(configManager.getConfiguration("runelite", MINIGAME_PILOT_KEY)), nextUp, s.isQuiet(), skipped,
			sources(in, s, plan, loggedIn, now), budget, fit);
		SwingUtilities.invokeLater(() -> p.update(view));
	}

	/** Times the run being worked and keeps what it learns in Autopilot's own profile settings. On the client thread. */
	private void learn(List<Candidate> all, Candidate top, long now, boolean on)
	{
		if (!on || pace == null)
		{
			watch.abandon();
			return;
		}
		List<PaceWatch.Sample> done = watch.observe(all, top == null ? null : top.getKey(), now);
		boolean changed = false;
		for (PaceWatch.Sample sample : done)
		{
			changed |= pace.add(sample.kind, sample.minutesPerStop);
		}
		if (changed)
		{
			String json = pace.toJson(gson);
			paceJson = json;
			configManager.setRSProfileConfiguration(CodexAutopilotConfig.GROUP, Pace.KEY, json);
		}
	}

	/** Sends what is new through RuneLite's notifier, once per change. On the client thread. */
	private void announce(List<Candidate> all, Plan plan, long now)
	{
		Set<String> visible = new HashSet<>();
		for (Candidate c : plan.getSteps())
		{
			visible.add(c.getKey());
		}
		boolean on = config.notifications();
		// Watched even with notifications off, so switching them on later does not announce old news.
		for (Heads.Notice n : heads.observe(all, visible, now, on && config.notifyWaste(), on && config.notifyReady()))
		{
			notifier.notify(n.text);
		}
	}

	private Pace pace(Profile profile)
	{
		String json = Profile.safe(profile, CodexAutopilotConfig.GROUP, Pace.KEY);
		if (pace == null || !Objects.equals(json, paceJson))
		{
			paceJson = json;
			pace = Pace.parse(gson, json);
		}
		return pace;
	}

	private GoalBoard board(Profile profile)
	{
		String json = Profile.safe(profile, GoalBoard.GROUP, GoalBoard.KEY);
		if (!Objects.equals(json, boardJson))
		{
			boardJson = json;
			board = GoalBoard.parse(gson, json);
		}
		return board;
	}

	private BankSnapshot bank(Profile profile)
	{
		String json = Profile.safe(profile, BankSnapshot.GROUP, BankSnapshot.KEY);
		if (!Objects.equals(json, bankJson))
		{
			bankJson = json;
			bank = BankSnapshot.parse(gson, json);
		}
		return bank;
	}

	private List<View.Source> sources(Advisor.Inputs in, Settings s, Plan plan, boolean loggedIn, long now)
	{
		List<View.Source> out = new ArrayList<>();
		int spots = in.seen == null ? 0 : in.seen.size();
		out.add(!s.isChores() ? off("Time Tracking")
			: new View.Source("Time Tracking", spots == 0 ? "Nothing seen" : spots + " tracked", spots > 0));
		long open = in.dailies == null ? 0 : in.dailies.stream().filter(DailyState::isClaimable).count();
		out.add(!s.isDailies() ? off("Dailies")
			: !loggedIn ? new View.Source("Dailies", "Log in", false)
			: new View.Source("Dailies", open == 0 ? "All claimed" : open + " open", true));
		out.add(!s.isKingdom() ? off("Kingdom")
			: in.kingdom == null ? new View.Source("Kingdom", "Not seen", false)
			: new View.Source("Kingdom", in.kingdom.approvalPercent() + "% approval", true));
		out.add(!s.isNavigator() ? off("Navigator")
			: in.board == null ? new View.Source("Navigator", "No goals", false)
			: new View.Source("Navigator", in.board.open() == 1 ? "1 goal" : in.board.open() + " goals", true));
		out.add(!s.isBankSteward() ? off("Bank Steward")
			: in.bank == null ? new View.Source("Bank Steward", "No bank", false)
			: new View.Source("Bank Steward", in.bank.getSavedAt() <= 0 ? "Bank known"
				: Format.shortDuration(now - in.bank.getSavedAt() / 1000) + " ago", true));
		long wasting = plan.count(Tier.WASTING);
		out.add(new View.Source("At risk", wasting == 0 ? "Nothing" : String.valueOf(wasting), wasting > 0));
		return out;
	}

	private static View.Source off(String label)
	{
		return new View.Source(label, "Off", false);
	}

	/**
	 * Reads only RuneLite core's own groups (Time Tracking, Kingdom of Miscellania), so the Codex
	 * readers above can cache their parsed JSON separately.
	 */
	private static final class OnlyCore implements Profile
	{
		private final Profile inner;

		OnlyCore(Profile inner)
		{
			this.inner = inner;
		}

		@Override
		public String get(String group, String key)
		{
			return GoalBoard.GROUP.equals(group) || BankSnapshot.GROUP.equals(group) || CodexAutopilotConfig.GROUP.equals(group)
				? null : inner.get(group, key);
		}
	}

	private final class PanelActions implements Actions
	{
		@Override
		public void skip(String key)
		{
			session.skip(key);
			skipped = true;
			clientThread.invokeLater(CodexAutopilotPlugin.this::evaluate);
		}

		@Override
		public void snooze(String key)
		{
			session.snooze(key, Instant.now().getEpochSecond());
			clientThread.invokeLater(CodexAutopilotPlugin.this::evaluate);
		}

		@Override
		public void budget(Budget budget)
		{
			configManager.setConfiguration(CodexAutopilotConfig.GROUP, CodexAutopilotConfig.BUDGET_KEY, budget);
		}

		@Override
		public void restore()
		{
			session.clear();
			skipped = false;
			clientThread.invokeLater(CodexAutopilotPlugin.this::evaluate);
		}
	}
}

package com.codex.autopilot.core;

import java.util.Collection;

/**
 * The minigames another Codex Pilot already guides, so Autopilot can step aside there instead of
 * nagging. Detection follows Codex Minigame Pilot: the Motherlode Mine's regions, the Blast
 * Furnace's region, and a Mahogany Homes contractor close by.
 */
public enum Activity
{
	NONE("", ""),
	MOTHERLODE("Motherlode Mine", "In the Motherlode Mine"),
	BLAST_FURNACE("Blast Furnace", "At the Blast Furnace"),
	MAHOGANY_HOMES("Mahogany Homes", "On a Mahogany Homes contract");

	static final int[] MOTHERLODE_REGIONS = {14679, 14680, 14681, 14935, 14936, 14937, 15191, 15192, 15193};
	static final int BLAST_FURNACE_REGION = 7757;
	/** The four Mahogany Homes contractors: Falador, Varrock, East Ardougne and Hosidius. */
	static final String[] CONTRACTORS = {"Amy", "Marlo", "Ellie", "Angelo"};

	private final String label;
	private final String where;

	Activity(String label, String where)
	{
		this.label = label;
		this.where = where;
	}

	public String getLabel()
	{
		return label;
	}

	/** "In the Motherlode Mine". */
	public String getWhere()
	{
		return where;
	}

	/**
	 * @param region the region the player stands in, or -1
	 * @param nearbyNpcs names of the NPCs close by, may be null
	 */
	public static Activity of(int region, Collection<String> nearbyNpcs)
	{
		for (int r : MOTHERLODE_REGIONS)
		{
			if (r == region)
			{
				return MOTHERLODE;
			}
		}
		if (region == BLAST_FURNACE_REGION)
		{
			return BLAST_FURNACE;
		}
		if (nearbyNpcs != null)
		{
			for (String n : nearbyNpcs)
			{
				if (n == null)
				{
					continue;
				}
				for (String c : CONTRACTORS)
				{
					if (c.equalsIgnoreCase(n.trim()))
					{
						return MAHOGANY_HOMES;
					}
				}
			}
		}
		return NONE;
	}
}

package com.codex.autopilot.core;

import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;

/**
 * Turns everything Autopilot reads into one ranked plan. Every source is optional: a missing or
 * damaged one simply adds no steps, and the reading of each is fenced off so one bad value
 * cannot stop the others.
 */
public final class Advisor
{
	/** Added to a chore's why line when Codex Rounds is on to guide the trip itself. */
	public static final String ROUNDS = "Codex Rounds has the route";

	private Advisor()
	{
	}

	/** Codex Rounds routes bird houses, trees and special patches; herb and hops runs are not on its round. */
	static boolean routedByRounds(Candidate.Kind kind)
	{
		return kind == Candidate.Kind.BIRDHOUSE_RUN || kind == Candidate.Kind.TREE_RUN || kind == Candidate.Kind.PATCH_RUN;
	}

	/** What was read for one evaluation. Any field may be empty or null. */
	public static final class Inputs
	{
		public Map<Spot, Seen> seen = Collections.emptyMap();
		public Growth.Offset offset = Growth.Offset.NONE;
		public Kingdom kingdom;
		/** Null while logged out: dailies are only read live. */
		public List<DailyState> dailies;
		public GoalBoard board;
		public BankSnapshot bank;
		/** The player's learned pace, or null to keep every estimate. */
		public Pace pace;

		/** Reads every config-backed source; dailies come from the live game and are added by the caller. */
		public static Inputs read(Profile profile, Gson gson, long now, boolean royalTrouble)
		{
			Inputs in = new Inputs();
			in.seen = Chores.readSeen(profile);
			in.offset = Chores.readOffset(profile);
			try
			{
				in.kingdom = KingdomWatch.read(profile, now, royalTrouble);
			}
			catch (RuntimeException e)
			{
				in.kingdom = null;
			}
			in.board = GoalBoard.read(profile, gson);
			in.bank = BankSnapshot.read(profile, gson);
			return in;
		}
	}

	/** Every step the sources the player has on would offer, unranked. */
	public static List<Candidate> candidates(Inputs in, Settings s, long now)
	{
		List<Candidate> out = new ArrayList<>();
		BankSnapshot bank = s.isBankSteward() ? in.bank : null;
		if (in.seen != null)
		{
			try
			{
				Growth.Offset offset = in.offset == null ? Growth.Offset.NONE : in.offset;
				for (Candidate c : Chores.candidates(Chores.read(watched(in.seen, s), now, offset), bank, now, offset))
				{
					if (in.pace != null)
					{
						c = in.pace.apply(c);
					}
					out.add(s.isRounds() && routedByRounds(c.getKind()) ? c.withNote(ROUNDS) : c);
				}
			}
			catch (RuntimeException e)
			{
				// Leave the chores out this time round.
			}
		}
		if (s.isKingdom())
		{
			Candidate k = KingdomWatch.candidate(in.kingdom, s, bank, now);
			if (k != null)
			{
				out.add(k);
			}
		}
		if (s.isDailies())
		{
			out.addAll(Dailies.candidates(in.dailies, s, bank, now));
		}
		if (s.isNavigator() && in.board != null)
		{
			out.addAll(in.board.candidates());
		}
		return out;
	}

	/** The spots the player's settings say to watch: the timed chores, the herb run and the hops run each have a switch. */
	static Map<Spot, Seen> watched(Map<Spot, Seen> seen, Settings s)
	{
		Map<Spot, Seen> out = new EnumMap<>(Spot.class);
		for (Map.Entry<Spot, Seen> e : seen.entrySet())
		{
			switch (e.getKey().getGroup())
			{
				case HERBS:
				case ALLOTMENTS:
				case FLOWERS:
					if (s.isHerbs())
					{
						out.put(e.getKey(), e.getValue());
					}
					break;
				case HOPS:
					if (s.isHops())
					{
						out.put(e.getKey(), e.getValue());
					}
					break;
				default:
					if (s.isChores())
					{
						out.put(e.getKey(), e.getValue());
					}
					break;
			}
		}
		return out;
	}

	/** What comes ready next among the chores, for when nothing is due. */
	public static String nextUp(Inputs in, Settings s, long now)
	{
		if (in.seen == null)
		{
			return null;
		}
		try
		{
			return Chores.nextUp(Chores.read(watched(in.seen, s), now, in.offset == null ? Growth.Offset.NONE : in.offset), now);
		}
		catch (RuntimeException e)
		{
			return null;
		}
	}

	public static Plan plan(Inputs in, Settings s, Session session, long now)
	{
		return Ranker.rank(candidates(in, s, now), s, session, now);
	}
}

package com.codex.autopilot.core;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonPrimitive;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;

/**
 * Codex Bank Steward's shared look at the bank, read and never written. Steward saves it per RS
 * profile under {@code codexbanksteward/bankV1}:
 * {@code {"version":1,"savedAt":1760000000000,"items":{"995":1234567,"1511":40},"truncated":false}}.
 * Autopilot only asks it whether a chore's supplies are banked. A missing, damaged or newer
 * version of the snapshot reads as no bank at all.
 */
public final class BankSnapshot
{
	public static final String GROUP = "codexbanksteward";
	public static final String KEY = "bankV1";

	private final Map<Integer, Long> items;
	private final long savedAt;
	private final boolean truncated;

	BankSnapshot(Map<Integer, Long> items, long savedAt, boolean truncated)
	{
		this.items = Collections.unmodifiableMap(items);
		this.savedAt = Math.max(0, savedAt);
		this.truncated = truncated;
	}

	/** A bank holding exactly these, for tests and previews. */
	public static BankSnapshot of(Map<Integer, Long> items, long savedAt)
	{
		return new BankSnapshot(new HashMap<>(items), savedAt, false);
	}

	public static BankSnapshot read(Profile profile, Gson gson)
	{
		return parse(gson, Profile.safe(profile, GROUP, KEY));
	}

	/** The snapshot, or null when there is none, it is damaged, or its version is newer than this reader. */
	public static BankSnapshot parse(Gson gson, String json)
	{
		if (gson == null || json == null || json.trim().isEmpty())
		{
			return null;
		}
		try
		{
			JsonElement root = gson.fromJson(json, JsonElement.class);
			if (root == null || !root.isJsonObject())
			{
				return null;
			}
			JsonObject o = root.getAsJsonObject();
			if (version(o) != 1)
			{
				return null;
			}
			JsonElement list = o.get("items");
			if (list == null || !list.isJsonObject())
			{
				return null;
			}
			Map<Integer, Long> items = new HashMap<>();
			for (Map.Entry<String, JsonElement> e : list.getAsJsonObject().entrySet())
			{
				int id;
				try
				{
					id = Integer.parseInt(e.getKey().trim());
				}
				catch (NumberFormatException ex)
				{
					continue;
				}
				long qty = number(e.getValue(), 0);
				if (id >= 0 && qty > 0)
				{
					// No bank stack passes the integer cap; a bigger figure is damage, held there.
					items.merge(id, Math.min(qty, Integer.MAX_VALUE), (a, b) -> Math.min(Integer.MAX_VALUE, a + b));
				}
			}
			JsonElement t = o.get("truncated");
			boolean truncated = t != null && t.isJsonPrimitive() && t.getAsJsonPrimitive().isBoolean() && t.getAsBoolean();
			return new BankSnapshot(items, number(o.get("savedAt"), 0), truncated);
		}
		catch (RuntimeException e)
		{
			return null;
		}
	}

	/** The saved version: 1 when missing (the first writers left it out), -1 when it is not a number. */
	static long version(JsonObject o)
	{
		JsonElement v = o.get("version");
		if (v == null || v.isJsonNull())
		{
			return 1;
		}
		return v.isJsonPrimitive() && v.getAsJsonPrimitive().isNumber() ? number(v, -1) : -1;
	}

	/** A whole number from a JSON value, or the fallback when it is missing or not a finite number. */
	static long number(JsonElement e, long fallback)
	{
		if (e == null || !e.isJsonPrimitive())
		{
			return fallback;
		}
		JsonPrimitive p = e.getAsJsonPrimitive();
		if (!p.isNumber())
		{
			return fallback;
		}
		double d = p.getAsDouble();
		if (Double.isNaN(d) || Double.isInfinite(d))
		{
			return fallback;
		}
		if (d >= Long.MAX_VALUE)
		{
			return Long.MAX_VALUE;
		}
		if (d <= Long.MIN_VALUE)
		{
			return Long.MIN_VALUE;
		}
		return (long) d;
	}

	/** How many of any of these items are banked. */
	public long count(int... ids)
	{
		long n = 0;
		for (int id : ids)
		{
			n += items.getOrDefault(id, 0L);
		}
		return n;
	}

	public long count(Need need)
	{
		return count(need.getIds());
	}

	/** Unix milliseconds the bank was last seen, or 0. */
	public long getSavedAt()
	{
		return savedAt;
	}

	/** True when Steward could not save every item, so a missing one may still be there. */
	public boolean isTruncated()
	{
		return truncated;
	}

	public int size()
	{
		return items.size();
	}
}

package com.codex.autopilot.core;

import net.runelite.api.gameval.ItemID;

/**
 * Bird house spaces on Fossil Island. The space's player variable is 0 when empty, and otherwise
 * encodes the house type and whether it has seeds: (type * 3) + 1 built, + 3 seeded (RuneLite's
 * BirdHouseState). Seeded houses fill up 50 minutes after the seeds go in.
 */
public final class Birdhouse
{
	public static final int FILL_SECONDS = 50 * 60;
	public static final int SEEDS_PER_HOUSE = 10;

	/** Seeds a bird house takes, any one kind, ten at a time. */
	public static final int[] SEEDS = {
		ItemID.BARLEY_SEED, ItemID.HAMMERSTONE_HOP_SEED, ItemID.ASGARNIAN_HOP_SEED, ItemID.JUTE_SEED,
		ItemID.YANILLIAN_HOP_SEED, ItemID.KRANDORIAN_HOP_SEED, ItemID.WILDBLOOD_HOP_SEED,
	};

	public enum State
	{
		EMPTY,
		BUILT,
		SEEDED,
		UNKNOWN
	}

	public enum Type
	{
		NORMAL("Bird house", ItemID.BIRDHOUSE_NORMAL, ItemID.LOGS, 5, 5),
		OAK("Oak bird house", ItemID.BIRDHOUSE_OAK, ItemID.OAK_LOGS, 14, 15),
		WILLOW("Willow bird house", ItemID.BIRDHOUSE_WILLOW, ItemID.WILLOW_LOGS, 24, 25),
		TEAK("Teak bird house", ItemID.BIRDHOUSE_TEAK, ItemID.TEAK_LOGS, 34, 35),
		MAPLE("Maple bird house", ItemID.BIRDHOUSE_MAPLE, ItemID.MAPLE_LOGS, 44, 45),
		MAHOGANY("Mahogany bird house", ItemID.BIRDHOUSE_MAHOGANY, ItemID.MAHOGANY_LOGS, 49, 50),
		YEW("Yew bird house", ItemID.BIRDHOUSE_YEW, ItemID.YEW_LOGS, 59, 60),
		MAGIC("Magic bird house", ItemID.BIRDHOUSE_MAGIC, ItemID.MAGIC_LOGS, 74, 75),
		REDWOOD("Redwood bird house", ItemID.BIRDHOUSE_REDWOOD, ItemID.REDWOOD_LOGS, 89, 90);

		private final String name;
		private final int itemId;
		private final int logId;
		private final int hunterLevel;
		private final int craftingLevel;

		Type(String name, int itemId, int logId, int hunterLevel, int craftingLevel)
		{
			this.name = name;
			this.itemId = itemId;
			this.logId = logId;
			this.hunterLevel = hunterLevel;
			this.craftingLevel = craftingLevel;
		}

		public String getName()
		{
			return name;
		}

		public int getItemId()
		{
			return itemId;
		}

		public int getLogId()
		{
			return logId;
		}

		public int getHunterLevel()
		{
			return hunterLevel;
		}

		public int getCraftingLevel()
		{
			return craftingLevel;
		}

		/** The best house a Hunter level can place. */
		public static Type bestFor(int hunter)
		{
			Type best = NORMAL;
			for (Type t : values())
			{
				if (t.hunterLevel <= hunter)
				{
					best = t;
				}
			}
			return best;
		}

		public static Type forItem(int itemId)
		{
			for (Type t : values())
			{
				if (t.itemId == itemId)
				{
					return t;
				}
			}
			return null;
		}
	}

	private Birdhouse()
	{
	}

	public static State state(int varp)
	{
		if (varp == 0)
		{
			return State.EMPTY;
		}
		if (varp < 0 || varp > Type.values().length * 3)
		{
			return State.UNKNOWN;
		}
		return varp % 3 == 0 ? State.SEEDED : State.BUILT;
	}

	public static Type type(int varp)
	{
		if (varp <= 0 || varp > Type.values().length * 3)
		{
			return null;
		}
		return Type.values()[(varp - 1) / 3];
	}
}

package com.codex.autopilot.core;

import java.util.List;

/**
 * Says what to take for a chore, checked against the banked snapshot when there is one: "Bring 4
 * oak logs + 40 seeds", or "You're out of hop seeds" when the bank has none. It stays light: no
 * pull list, just the one line that saves a wasted trip.
 */
public final class Bring
{
	private Bring()
	{
	}

	/** The line to show, or null when there is nothing to bring. */
	public static String line(List<Need> needs, BankSnapshot bank)
	{
		StringBuilder list = new StringBuilder();
		for (Need n : needs)
		{
			if (n.getAmount() <= 0)
			{
				continue;
			}
			if (bank != null)
			{
				long have = bank.count(n);
				if (have <= 0 && !bank.isTruncated())
				{
					return "You're out of " + n.getName();
				}
				if (have > 0 && have < n.getAmount())
				{
					return "Only " + Format.number(have) + " " + n.getName() + " banked, " + Format.number(n.getAmount()) + " needed";
				}
			}
			if (list.length() > 0)
			{
				list.append(" + ");
			}
			list.append(Format.number(n.getAmount())).append(' ').append(n.getName());
		}
		return list.length() == 0 ? null : "Bring " + list;
	}

	/** Whether the line warns of something missing. */
	public static boolean isShort(String line)
	{
		return line != null && (line.startsWith("You're out of") || line.startsWith("Only "));
	}
}

package com.codex.autopilot.core;

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;

/**
 * "I have 30 minutes": the best set of steps that fits. Anything going to waste is taken first,
 * in the plan's order; then the rest by what they save per minute spent, the way the plan
 * weighs chores, skipped steps last. Each step that still fits is taken and one that does not is
 * passed over, so a long run does not keep two short ones out.
 */
public enum Budget
{
	NONE("No limit", 0),
	MIN_15("15 min", 15),
	MIN_30("30 min", 30),
	MIN_60("60 min", 60);

	private final String label;
	private final int minutes;

	Budget(String label, int minutes)
	{
		this.label = label;
		this.minutes = minutes;
	}

	/** Minutes to fill, or 0 for no limit. */
	public int getMinutes()
	{
		return minutes;
	}

	/** "15", "30", "60" or "Any", for the selector. */
	public String getShort()
	{
		return minutes == 0 ? "Any" : String.valueOf(minutes);
	}

	@Override
	public String toString()
	{
		return label;
	}

	/** What fits the budget. */
	public static final class Fit
	{
		public static final Fit NONE = new Fit(Collections.emptyList(), 0, 0, 0);

		private final List<Candidate> steps;
		private final int total;
		private final int left;
		private final int shortest;

		Fit(List<Candidate> steps, int total, int left, int shortest)
		{
			this.steps = Collections.unmodifiableList(steps);
			this.total = total;
			this.left = left;
			this.shortest = shortest;
		}

		/** The steps chosen, in the order to do them. */
		public List<Candidate> getSteps()
		{
			return steps;
		}

		/** Minutes they take together. */
		public int getTotal()
		{
			return total;
		}

		/** Steps left for another time. */
		public int getLeft()
		{
			return left;
		}

		/** Minutes of the quickest step left out, or 0 when none was. */
		public int getShortest()
		{
			return shortest;
		}

		public Candidate first()
		{
			return steps.isEmpty() ? null : steps.get(0);
		}

		public boolean isEmpty()
		{
			return steps.isEmpty();
		}
	}

	/** The steps of a ranked plan that fit in {@code minutes}; everything when there is no limit. */
	public static Fit fit(Plan plan, int minutes, Session session)
	{
		if (plan == null || plan.isEmpty())
		{
			return Fit.NONE;
		}
		List<Candidate> ranked = plan.getSteps();
		if (minutes <= 0)
		{
			int total = 0;
			for (Candidate c : ranked)
			{
				total += c.getMinutes();
			}
			return new Fit(new ArrayList<>(ranked), total, 0, 0);
		}
		List<Candidate> order = new ArrayList<>(ranked);
		order.sort(Comparator
			.comparingInt((Candidate c) -> session != null && session.skipOrder(c.getKey()) > 0 ? 1 : 0)
			.thenComparingInt(c -> c.getTier() == Tier.WASTING ? 0 : 1)
			.thenComparingDouble(c -> c.getTier() == Tier.WASTING ? ranked.indexOf(c) : -c.density())
			.thenComparingInt(ranked::indexOf));
		List<Candidate> chosen = new ArrayList<>();
		int total = 0;
		int shortest = 0;
		for (Candidate c : order)
		{
			if (total + c.getMinutes() <= minutes)
			{
				chosen.add(c);
				total += c.getMinutes();
			}
			else if (shortest == 0 || c.getMinutes() < shortest)
			{
				shortest = c.getMinutes();
			}
		}
		return new Fit(chosen, total, ranked.size() - chosen.size(), shortest);
	}
}

package com.codex.autopilot.core;

import java.util.Objects;

/**
 * One thing the account could do next, with what is lost by waiting and how long it takes.
 *
 * <p>Urgency is what an hour of delay costs, as a share of the chore's own cycle: a full bird
 * house idles a whole run every 50 minutes, so four of them cost 4.8 an hour; a grown calquat
 * idles a fraction of its 19 hour growth. A deadline is when something is lost for good.</p>
 */
public final class Candidate
{
	/** What a step is, for its icon, colour and stable key. */
	public enum Kind
	{
		BIRDHOUSE_RUN("Birdhouse run"),
		TREE_RUN("Tree run"),
		PATCH_RUN("Special patches"),
		HERB_RUN("Herb run"),
		HOPS_RUN("Hops run"),
		DAILIES("Diary dailies"),
		CONTRACT("Farming contract"),
		KINGDOM("Kingdom of Miscellania"),
		FOCUS_GOAL("Focused goal"),
		GOAL("Goal");

		private final String label;

		Kind(String label)
		{
			this.label = label;
		}

		public String getLabel()
		{
			return label;
		}

		/** A timed farming or Fossil Island trip, the kind Codex Rounds routes. */
		public boolean isChore()
		{
			return this == BIRDHOUSE_RUN || this == TREE_RUN || this == PATCH_RUN || this == HERB_RUN || this == HOPS_RUN;
		}
	}

	private final String key;
	private final Kind kind;
	private final Tier tier;
	private final String over;
	private final String title;
	private final String why;
	private final String bring;
	private final int minutes;
	private final double urgency;
	private final long deadline;
	private final int count;
	private final int itemId;
	private final boolean paced;

	public Candidate(String key, Kind kind, Tier tier, String over, String title, String why, String bring,
		int minutes, double urgency, long deadline, int count, int itemId)
	{
		this(key, kind, tier, over, title, why, bring, minutes, urgency, deadline, count, itemId, false);
	}

	private Candidate(String key, Kind kind, Tier tier, String over, String title, String why, String bring,
		int minutes, double urgency, long deadline, int count, int itemId, boolean paced)
	{
		this.key = key;
		this.kind = kind;
		this.tier = tier;
		this.over = over;
		this.title = title;
		this.why = why;
		this.bring = bring;
		this.minutes = Math.max(1, minutes);
		this.urgency = Double.isNaN(urgency) || urgency < 0 ? 0 : urgency;
		this.deadline = Math.max(0, deadline);
		this.count = count;
		this.itemId = itemId;
		this.paced = paced;
	}

	/** The same step taking the player's own learned time instead of the estimate. */
	public Candidate withPace(int minutes)
	{
		return new Candidate(key, kind, tier, over, title, why, bring, minutes, urgency, deadline, count, itemId, true);
	}

	/** The same step with a note added to its why line. */
	public Candidate withNote(String note)
	{
		String w = why == null || why.isEmpty() ? note : why + "; " + note;
		return new Candidate(key, kind, tier, over, title, w, bring, minutes, urgency, deadline, count, itemId, paced);
	}

	/** Stable for the session, so Skip and Snooze stick to the same chore or goal. */
	public String getKey()
	{
		return key;
	}

	public Kind getKind()
	{
		return kind;
	}

	public Tier getTier()
	{
		return tier;
	}

	/** The small line above the title, such as "Birdhouse run" or "Toward Quest cape". */
	public String getOver()
	{
		return over;
	}

	/** The step itself in a few words, such as "4 ready, 2 seaweed ready". */
	public String getTitle()
	{
		return title;
	}

	/** One line on why it is here and why now. */
	public String getWhy()
	{
		return why;
	}

	/** What to take along, or null. */
	public String getBring()
	{
		return bring;
	}

	/** About how many minutes it takes. */
	public int getMinutes()
	{
		return minutes;
	}

	/** True when the minutes are the player's own pace, learned from their runs, rather than an estimate. */
	public boolean isPaced()
	{
		return paced;
	}

	public double getUrgency()
	{
		return urgency;
	}

	/** Unix second it goes to waste, or 0 when nothing is lost for good. */
	public long getDeadline()
	{
		return deadline;
	}

	/** How many chores it covers, or 1. */
	public int getCount()
	{
		return count;
	}

	/** An item to show beside it, or -1. */
	public int getItemId()
	{
		return itemId;
	}

	/** The whole step as one line, such as "Birdhouse run: 4 ready, 2 seaweed ready". */
	public String headline()
	{
		return over == null || over.isEmpty() ? title : over + ": " + title;
	}

	/** Urgency per minute spent, so quick, valuable chores come first. */
	public double density()
	{
		return urgency / minutes;
	}

	@Override
	public boolean equals(Object o)
	{
		if (!(o instanceof Candidate))
		{
			return false;
		}
		Candidate c = (Candidate) o;
		return key.equals(c.key) && tier == c.tier && minutes == c.minutes && paced == c.paced && deadline == c.deadline && count == c.count
			&& Objects.equals(title, c.title) && Objects.equals(why, c.why) && Objects.equals(bring, c.bring);
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(key, tier, title, why, minutes, deadline);
	}

	@Override
	public String toString()
	{
		return tier + " " + headline() + " (" + minutes + " min)";
	}
}

package com.codex.autopilot.core;

import com.codex.autopilot.core.farming.CropState;
import com.codex.autopilot.core.farming.PatchState;
import com.codex.autopilot.core.farming.Produce;
import java.util.ArrayList;
import java.util.EnumMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.gameval.ItemID;

/**
 * The timed chores RuneLite's Time Tracking plugin already knows about, read the way Codex Rounds
 * reads them, and grouped into the trips that make sense together: one Fossil Island trip for bird
 * houses, seaweed and its hardwoods, one tree run, one for the special patches.
 */
public final class Chores
{
	public static final String GROUP = "timetracking";
	public static final String OFFSET_KEY = "farmTickOffset";
	public static final String PRECISION_KEY = "farmTickOffsetPrecision";

	/** Ready within this long joins the note on the step: "2 more ready in 6 min". */
	static final long SOON = 15 * 60;
	/** A dead patch left this long is taken as abandoned. */
	static final long FALLOW_AFTER = 2 * 86_400;

	private Chores()
	{
	}

	/** Every spot Time Tracking has saved, skipping anything it cannot read. */
	public static Map<Spot, Seen> readSeen(Profile profile)
	{
		Map<Spot, Seen> out = new EnumMap<>(Spot.class);
		for (Spot s : Spot.values())
		{
			Seen seen;
			try
			{
				seen = Seen.parse(Profile.safe(profile, GROUP, s.timeTrackingKey()));
			}
			catch (RuntimeException e)
			{
				seen = null;
			}
			if (seen != null && seen.getValue() >= 0)
			{
				out.put(s, seen);
			}
		}
		return out;
	}

	public static Growth.Offset readOffset(Profile profile)
	{
		return new Growth.Offset(integer(Profile.safe(profile, GROUP, OFFSET_KEY)), integer(Profile.safe(profile, GROUP, PRECISION_KEY)));
	}

	static Integer integer(String s)
	{
		if (s == null)
		{
			return null;
		}
		try
		{
			return Integer.parseInt(s.trim());
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}

	/** Each saved spot as it stands now. A value the farming tables do not know reads as unseen. */
	public static Map<Spot, Reading> read(Map<Spot, Seen> seen, long now, Growth.Offset offset)
	{
		Map<Spot, Reading> out = new EnumMap<>(Spot.class);
		for (Map.Entry<Spot, Seen> e : seen.entrySet())
		{
			try
			{
				out.put(e.getKey(), Growth.read(e.getKey(), e.getValue(), now, offset));
			}
			catch (RuntimeException ex)
			{
				// A value outside the tables: leave the spot out rather than guess.
			}
		}
		return out;
	}

	/** What comes ready next, such as "Bird houses full in 23 min", or null when nothing is growing. */
	public static String nextUp(Map<Spot, Reading> readings, long now)
	{
		Reading next = null;
		for (Reading r : readings.values())
		{
			Spot.Group g = r.getSpot().getGroup();
			if (g == Spot.Group.ALLOTMENTS || g == Spot.Group.FLOWERS)
			{
				// They ride along on the herb run; a flower ready in 3 min is not worth a line of its own.
				continue;
			}
			if (r.getStatus() == Status.GROWING && r.getReadyAt() > now && (next == null || r.getReadyAt() < next.getReadyAt()))
			{
				next = r;
			}
		}
		if (next == null)
		{
			return null;
		}
		String in = Format.duration(next.getReadyAt() - now);
		Spot s = next.getSpot();
		return s.isBirdhouse() ? "Bird houses full in " + in : s.kindName() + " at " + s.getLabel() + " ready in " + in;
	}

	/** The trip a spot belongs to. */
	static Candidate.Kind trip(Spot s)
	{
		if (s.isFossilIsland())
		{
			return Candidate.Kind.BIRDHOUSE_RUN;
		}
		switch (s.getGroup())
		{
			case PATCHES:
				return Candidate.Kind.PATCH_RUN;
			case HERBS:
			case ALLOTMENTS:
			case FLOWERS:
				return Candidate.Kind.HERB_RUN;
			case HOPS:
				return Candidate.Kind.HOPS_RUN;
			default:
				return Candidate.Kind.TREE_RUN;
		}
	}

	/** Minutes a chore takes to come round again, so an hour idle can be weighed as a share of it. */
	static double cycleMinutes(Spot s, Reading r)
	{
		if (s.isBirdhouse())
		{
			return Birdhouse.FILL_SECONDS / 60.0;
		}
		PatchState p = r.getPatch();
		if (p != null && !p.isEmpty() && p.getProduce() != null && p.getProduce().getTickrate() > 0)
		{
			return p.getProduce().getTickrate() * (double) Math.max(1, p.getStages() - 1);
		}
		switch (s.getGroup())
		{
			case SEAWEED:
				return 40;
			case HARDWOODS:
				return 640 * 7;
			case SPIRIT_TREES:
				return 320 * 11;
			case TREES:
				return 160 * 7;
			case HERBS:
				return 80;
			case ALLOTMENTS:
			case HOPS:
				return 60;
			case FLOWERS:
				return 20;
			default:
				return 80 * 7;
		}
	}

	/**
	 * Whether a spot looks deliberately left alone: weeds or bare soil, an empty bird house space,
	 * or a patch that died days ago. Those are not nagged about; a full house or a grown tree is.
	 */
	static boolean fallow(Reading r, long now)
	{
		if (r.isEmpty() || r.getHouse() == Birdhouse.State.EMPTY)
		{
			return true;
		}
		PatchState p = r.getPatch();
		return p != null && (p.getCropState() == CropState.DEAD || p.getCropState() == CropState.DISEASED) && r.getSeen() != null && now - r.getSeen().getTime() > FALLOW_AFTER;
	}

	/** Whether the reading is a diseased patch, which dies at its next growth tick unless cured. */
	static boolean diseased(Reading r)
	{
		PatchState p = r.getPatch();
		return p != null && p.getCropState() == CropState.DISEASED;
	}

	/** When a diseased patch dies: its next growth tick after it was seen. */
	static long dies(Reading r, Growth.Offset offset)
	{
		Produce produce = r.getPatch().getProduce();
		int rate = produce == null || produce.getTickrate() <= 0 ? 5 : produce.getTickrate();
		return Growth.tickTime(rate, 1, r.getSeen().getTime(), offset);
	}

	/** The grouped steps for everything ready. */
	public static List<Candidate> candidates(Map<Spot, Reading> readings, BankSnapshot bank, long now, Growth.Offset offset)
	{
		Map<Candidate.Kind, List<Reading>> ready = new EnumMap<>(Candidate.Kind.class);
		Map<Candidate.Kind, List<Reading>> soon = new EnumMap<>(Candidate.Kind.class);
		for (Reading r : readings.values())
		{
			Candidate.Kind k = trip(r.getSpot());
			if (r.getStatus() == Status.READY && !fallow(r, now))
			{
				ready.computeIfAbsent(k, x -> new ArrayList<>()).add(r);
			}
			else if (r.getStatus() == Status.GROWING && r.getReadyAt() > now && r.getReadyAt() - now <= SOON)
			{
				soon.computeIfAbsent(k, x -> new ArrayList<>()).add(r);
			}
		}
		List<Candidate> out = new ArrayList<>();
		for (Map.Entry<Candidate.Kind, List<Reading>> e : ready.entrySet())
		{
			List<Reading> near = soon.getOrDefault(e.getKey(), new ArrayList<>());
			if (e.getKey() == Candidate.Kind.HERB_RUN || e.getKey() == Candidate.Kind.HOPS_RUN)
			{
				Candidate c = HerbRun.step(e.getKey(), e.getValue(), near, bank, now, offset);
				if (c != null)
				{
					out.add(c);
				}
			}
			else
			{
				out.add(step(e.getKey(), e.getValue(), near, bank, now, offset));
			}
		}
		return out;
	}

	private static Candidate step(Candidate.Kind kind, List<Reading> list, List<Reading> soon, BankSnapshot bank, long now, Growth.Offset offset)
	{
		double urgency = 0;
		long idleSince = Long.MAX_VALUE;
		Reading sick = null;
		long dies = Long.MAX_VALUE;
		int houses = 0;
		int seaweed = 0;
		int trees = 0;
		int dead = 0;
		Set<String> names = new LinkedHashSet<>();
		for (Reading r : list)
		{
			Spot s = r.getSpot();
			if (diseased(r))
			{
				long d = dies(r, offset);
				if (d > now)
				{
					if (d < dies)
					{
						dies = d;
						sick = r;
					}
				}
				else
				{
					// Seen diseased a growth tick or more ago: it has died by now unless it was cured.
					dead++;
				}
			}
			urgency += 60.0 / cycleMinutes(s, r);
			if (r.getReadyAt() > 0 && r.getReadyAt() <= now)
			{
				idleSince = Math.min(idleSince, r.getReadyAt());
			}
			if (s.isBirdhouse())
			{
				houses++;
			}
			else if (s.getGroup() == Spot.Group.SEAWEED)
			{
				seaweed++;
			}
			else
			{
				trees++;
				names.add(s.kindName().toLowerCase());
			}
		}

		String over;
		String title;
		int minutes;
		int item;
		switch (kind)
		{
			case BIRDHOUSE_RUN:
			{
				over = houses > 0 ? "Birdhouse run" : "Fossil Island run";
				List<String> parts = new ArrayList<>();
				if (houses > 0)
				{
					parts.add(houses + " ready");
				}
				if (seaweed > 0)
				{
					parts.add(seaweed + " seaweed ready");
				}
				if (trees > 0)
				{
					parts.add(trees + (trees == 1 ? " hardwood" : " hardwoods") + " ready");
				}
				title = String.join(", ", parts);
				minutes = (int) Math.round(2 + houses * 1.0 + (seaweed > 0 ? 1.5 + seaweed * 1.5 : 0) + trees * 1.0);
				item = houses > 0 ? ItemID.BIRDHOUSE_NORMAL : seaweed > 0 ? ItemID.GIANT_SEAWEED : ItemID.TEAK_LOGS;
				break;
			}
			case TREE_RUN:
				over = "Tree run";
				title = trees + " ready: " + String.join(", ", names);
				minutes = (int) Math.round(trees * 3.0);
				item = produceItem(list, ItemID.PLANTPOT_CALQUAT_SAPLING);
				break;
			default:
				over = "Special patches";
				title = trees + " ready: " + String.join(", ", names);
				minutes = (int) Math.round(trees * 2.5);
				item = produceItem(list, ItemID.CACTUS_SPINE);
				break;
		}

		String why;
		Tier tier = Tier.READY;
		long deadline = 0;
		if (sick != null)
		{
			tier = Tier.WASTING;
			deadline = dies;
			why = sick.getSpot().kindName() + " at " + sick.getSpot().getLabel() + " is diseased: cure it within "
				+ Format.duration(dies - now) + " or it dies";
			urgency += 60.0 / Math.max(5, (dies - now) / 60.0);
		}
		else if (dead > 0)
		{
			why = dead == 1 ? "A diseased patch has likely died: clear it and replant" : dead + " diseased patches have likely died: clear and replant";
		}
		else if (idleSince != Long.MAX_VALUE && now - idleSince >= 60)
		{
			String idle = Format.duration(now - idleSince);
			switch (kind)
			{
				case BIRDHOUSE_RUN:
					why = houses > 0 ? "Full for " + idle + ": every 50 min idle is a run lost"
						: "Ready for " + idle + ": it grows nothing until you replant";
					break;
				case TREE_RUN:
					why = "Grown for " + idle + ": the next cycle starts when you replant";
					break;
				default:
					why = "Ready for " + idle + ": pick and replant to keep them growing";
					break;
			}
		}
		else
		{
			why = kind == Candidate.Kind.BIRDHOUSE_RUN && houses > 0 ? "Ready now: a house without seed catches nothing"
				: "Ready now: nothing grows there until you see to it";
		}
		if (!soon.isEmpty())
		{
			long first = Long.MAX_VALUE;
			for (Reading r : soon)
			{
				first = Math.min(first, r.getReadyAt());
			}
			why += "; " + soon.size() + " more ready in " + Format.duration(first - now);
		}

		String bring = kind == Candidate.Kind.BIRDHOUSE_RUN ? Bring.line(fossilNeeds(list), bank) : null;
		return new Candidate("chores:" + kind.name().toLowerCase(), kind, tier, over, title, why, bring,
			minutes, urgency, deadline, list.size(), item);
	}

	private static int produceItem(List<Reading> list, int fallback)
	{
		for (Reading r : list)
		{
			Produce p = r.getProduce();
			if (p != null && p.getItemId() > 0)
			{
				return p.getItemId();
			}
		}
		return fallback;
	}

	/** Logs and seeds to reset the houses, spores for the seabed. */
	static List<Need> fossilNeeds(List<Reading> list)
	{
		int rebuild = 0;
		int seed = 0;
		int spores = 0;
		Map<Birdhouse.Type, Integer> types = new EnumMap<>(Birdhouse.Type.class);
		for (Reading r : list)
		{
			Spot s = r.getSpot();
			if (s.isBirdhouse())
			{
				Birdhouse.State st = r.getHouse();
				Birdhouse.Type t = r.getSeen() == null ? null : Birdhouse.type(r.getSeen().getValue());
				if (t != null)
				{
					types.merge(t, 1, Integer::sum);
				}
				if (st == Birdhouse.State.SEEDED)
				{
					rebuild++;
				}
				if (st != Birdhouse.State.UNKNOWN)
				{
					seed++;
				}
			}
			else if (s.getGroup() == Spot.Group.SEAWEED)
			{
				spores++;
			}
		}
		List<Need> out = new ArrayList<>();
		Birdhouse.Type type = null;
		int best = 0;
		for (Map.Entry<Birdhouse.Type, Integer> e : types.entrySet())
		{
			if (e.getValue() > best || e.getValue() == best && type != null && e.getKey().ordinal() > type.ordinal())
			{
				type = e.getKey();
				best = e.getValue();
			}
		}
		if (rebuild > 0 && type != null)
		{
			out.add(new Need(logName(type), rebuild, type.getLogId(), type.getItemId()));
		}
		if (seed > 0)
		{
			out.add(new Need("hop seeds", seed * Birdhouse.SEEDS_PER_HOUSE, Birdhouse.SEEDS));
		}
		if (spores > 0)
		{
			out.add(new Need(spores == 1 ? "seaweed spore" : "seaweed spores", spores, ItemID.SEAWEED_SEED));
		}
		return out;
	}

	static String logName(Birdhouse.Type t)
	{
		return t == Birdhouse.Type.NORMAL ? "logs" : t.name().toLowerCase() + " logs";
	}
}

package com.codex.autopilot.core;

import com.codex.autopilot.core.farming.Produce;
import net.runelite.api.gameval.VarbitID;

/**
 * Guildmaster Jane's farming contracts. The contract's crop is a varbit whose values follow RuneLite's Time Tracking
 * plugin; the guild patches Rounds tends (bush, cactus, celastrus, redwood) are planted with the contract crop.
 */
public final class Contract
{
	private static final String[] NAMES = new String[52];

	static
	{
		String[] list = {
			"", "Redberry", "Cadavaberry", "Dwellberry", "Jangerberry", "Whiteberry", "Poison ivy",
			"Oak", "Willow", "Maple", "Yew", "Magic",
			"Apple", "Banana", "Orange", "Curry", "Pineapple", "Papaya", "Palm", "Dragonfruit",
			"Guam", "Marrentill", "Tarromin", "Harralander", "Ranarr", "Toadflax", "Irit", "Avantoe", "Kwuarm",
			"Snapdragon", "Cadantine", "Lantadyme", "Dwarf weed", "Torstol",
			"Marigold", "Rosemary", "Nasturtium", "Woad", "Limpwurt", "White lily",
			"Potato", "Onion", "Cabbage", "Tomato", "Sweetcorn", "Strawberry", "Watermelon", "Snape grass",
			"Cactus", "Potato cactus", "Redwood", "Celastrus",
		};
		System.arraycopy(list, 0, NAMES, 0, list.length);
	}

	private Contract()
	{
	}

	public static int type(Vars v)
	{
		return v.varbit(VarbitID.FARMGUILD_CONTRACT_TYPE);
	}

	public static boolean complete(Vars v)
	{
		return v.varbit(VarbitID.FARMGUILD_CONTRACT_COMPLETE) > 0;
	}

	/** Whether the player has ever been offered contracts. */
	public static boolean known(Vars v)
	{
		return v.varbit(VarbitID.FARMGUILD_CONTRACT_DISCUSSED) > 0 || type(v) > 0 || v.varbit(VarbitID.FARMGUILD_CONTRACT_COUNT) > 0;
	}

	/** The crop's name, or null for no contract or an unknown one. */
	public static String cropName(int type)
	{
		return type > 0 && type < NAMES.length ? NAMES[type] : null;
	}

	/** Which guild patch the crop grows in, for the board. */
	public static String patch(int type)
	{
		if (type >= 1 && type <= 6)
		{
			return "bush patch";
		}
		if (type <= 11)
		{
			return "tree patch";
		}
		if (type <= 19)
		{
			return "fruit tree patch";
		}
		if (type <= 33)
		{
			return "herb patch";
		}
		if (type <= 39)
		{
			return "flower patch";
		}
		if (type <= 47)
		{
			return "allotment";
		}
		if (type <= 49)
		{
			return "cactus patch";
		}
		return type == 50 ? "redwood patch" : "celastrus patch";
	}

	/** The crop when it grows in a guild patch Rounds tends, else null. */
	public static Produce produce(int type)
	{
		switch (type)
		{
			case 1:
				return Produce.REDBERRIES;
			case 2:
				return Produce.CADAVABERRIES;
			case 3:
				return Produce.DWELLBERRIES;
			case 4:
				return Produce.JANGERBERRIES;
			case 5:
				return Produce.WHITEBERRIES;
			case 6:
				return Produce.POISON_IVY;
			case 48:
				return Produce.CACTUS;
			case 49:
				return Produce.POTATO_CACTUS;
			case 50:
				return Produce.REDWOOD;
			case 51:
				return Produce.CELASTRUS;
			default:
				return null;
		}
	}
}

package com.codex.autopilot.core;

import java.util.ArrayList;
import java.util.List;
import net.runelite.api.gameval.ItemID;

/**
 * The diary dailies still to collect today, read live from the game the way Codex Rounds reads
 * them, as one step. What is not collected by midnight UTC is gone, so they count as going to
 * waste once the reset is near. A finished farming contract becomes its own step: it waits
 * for you, so it never goes to waste.
 */
public final class Dailies
{
	private Dailies()
	{
	}

	public static List<DailyState> read(Vars v)
	{
		List<DailyState> out = new ArrayList<>();
		for (Daily d : Daily.values())
		{
			try
			{
				out.add(DailyState.of(d, v));
			}
			catch (RuntimeException e)
			{
				// A varbit the client could not give: leave that daily out.
			}
		}
		return out;
	}

	public static List<Candidate> candidates(List<DailyState> states, Settings s, BankSnapshot bank, long now)
	{
		List<Candidate> out = new ArrayList<>();
		if (states == null)
		{
			return out;
		}
		List<DailyState> open = new ArrayList<>();
		DailyState contract = null;
		for (DailyState d : states)
		{
			if (d == null || !d.isClaimable())
			{
				continue;
			}
			if (d.getDaily().resetsDaily())
			{
				open.add(d);
			}
			else
			{
				contract = d;
			}
		}
		if (!open.isEmpty())
		{
			long reset = KingdomWatch.nextReset(now);
			boolean soon = reset - now <= s.getWasteHorizon();
			List<String> names = new ArrayList<>();
			List<Need> needs = new ArrayList<>();
			for (DailyState d : open)
			{
				names.add(d.getDaily().getLabel());
				if (d.getNeed() != null && d.getNeed().getAmount() > 0)
				{
					needs.add(d.getNeed());
				}
			}
			String title = open.size() == 1 ? names.get(0) : open.size() + " to collect";
			String why = (soon ? "Lost at the reset in " : "Not collected yet; the day resets in ") + Format.duration(reset - now)
				+ (open.size() > 1 ? ": " + String.join(", ", names) : "");
			out.add(new Candidate("dailies", Candidate.Kind.DAILIES, soon ? Tier.WASTING : Tier.READY, "Diary dailies", title, why,
				Bring.line(needs, bank), open.size() * 3, (soon ? 1.0 : 0.15) * open.size(), soon ? reset : 0, open.size(),
				open.size() == 1 ? open.get(0).getDaily().getItemId() : ItemID.BATTLESTAFF));
		}
		if (contract != null)
		{
			out.add(new Candidate("contract", Candidate.Kind.CONTRACT, Tier.READY, "Farming Guild", "See Guildmaster Jane",
				contract.getReward(), null, 3, contract.getReward().startsWith("Done") ? 0.3 : 0.05, 0, 1, Daily.CONTRACT.getItemId()));
		}
		return out;
	}
}

package com.codex.autopilot.core;

import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.NpcID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;

/**
 * The once-a-day buys and claims an account can pick up, as Codex Rounds reads them. Unlock and claimed checks follow RuneLite's
 * Daily Task Indicator plugin; amounts follow the diary reward tables.
 */
public enum Daily
{
	ZAFF("Zaff's battlestaves", "Varrock", ItemID.BATTLESTAFF, "Buy battlestaves from Zaff", NpcID.ZAFF),
	CROMPERTY("Cromperty's essence", "East Ardougne", ItemID.BLANKRUNE_HIGH, "Claim noted essence from Wizard Cromperty",
		NpcID.CROMPERTY_POST_DIARY, NpcID.CROMPERTY_PRE_DIARY),
	FLAX("Flax to bowstrings", "Seers' Village", ItemID.BOW_STRING, "Hand your flax to the Flax keeper", NpcID.DIARY_FLAX_KEEPER),
	RANTZ("Rantz's ogre arrows", "Feldip Hills", ItemID.OGRE_ARROW, "Claim ogre arrows from Rantz",
		NpcID.RANTZ, NpcID._100_RANTZ, NpcID._100_RANTZ1, NpcID._100_RANTZ2),
	ROBIN("Robin's bonemeal and slime", "Port Phasmatys", ItemID.POT_BONEMEAL, "Hand your bones to Robin", NpcID.AHOY_ROBIN),
	THIRUS("Thirus's dynamite", "Lovakengj", ItemID.LOVAKENGJ_DYNAMITE_FUSED, "Claim dynamite from Thirus",
		NpcID.LOVAKENGJ_THIRUS_POST_DIARY, NpcID.LOVAKENGJ_THIRUS, NpcID.LOVAKENGJ_THIRUS_PRE_DIARY),
	BERT("Bert's sand", "Yanille", ItemID.BUCKET_SAND, "Ask Bert for your sand", NpcID.HANDSAND_BERT_2OPS, NpcID.HANDSAND_BERT_1OP, NpcID.HANDSAND_BERT),
	HERB_BOXES("Herb boxes", "Nightmare Zone", ItemID.NZONE_HERBBOX, "Buy herb boxes from Dominic Onion", NpcID.NZONE_HOST),
	LUNDAIL("Lundail's runes", "Mage Arena", ItemID.DEATHRUNE, "Claim runes from Lundail", NpcID.MAGEARENA_RUNESHOP),
	/** Not daily, but a chore of the same shape: a talk at a place, ready again whenever a contract is done. */
	CONTRACT("Farming contract", "Farming Guild", ItemID.SEEDBOX, "Talk to Guildmaster Jane about your contract",
		NpcID.FARMING_GUILD_MASTER, NpcID.FARMING_GUILD_MASTER_1OP, NpcID.FARMING_GUILD_MASTER_2OP);

	public static final int ZAFF_PRICE = 7_000;
	public static final int HERB_BOX_POINTS = 9_500;
	public static final int HERB_BOX_MAX = 15;
	public static final int SAND_QUEST_COMPLETE = 160;
	public static final int ROBIN_PER_TIER = 13;
	/** Robin takes unnoted bones of any kind; the common ones count as packed. */
	static final int[] ROBIN_BONES = {ItemID.BONES, ItemID.BAT_BONES, ItemID.BIG_BONES, ItemID.BABYDRAGON_BONES, ItemID.DRAGON_BONES,
		ItemID.WOLF_BONES, ItemID.ZOGRE_BONES, ItemID.WYVERN_BONES, ItemID.LAVA_DRAGON_BONES};
	public static final int BERT_SAND = 84;

	private final String label;
	private final String place;
	private final int itemId;
	private final String action;
	private final int[] npcs;

	Daily(String label, String place, int itemId, String action, int... npcs)
	{
		this.label = label;
		this.place = place;
		this.itemId = itemId;
		this.action = action;
		this.npcs = npcs;
	}

	public String getLabel()
	{
		return label;
	}

	/** Where it is collected, such as "Varrock". */
	public String getPlace()
	{
		return place;
	}

	/** The item shown on the board for this daily. */
	public int getItemId()
	{
		return itemId;
	}

	/** What to do at the stop, as a step title. */
	public String getAction()
	{
		return action;
	}

	public int[] getNpcs()
	{
		return npcs.clone();
	}

	public boolean isNpc(int id)
	{
		for (int n : npcs)
		{
			if (n == id)
			{
				return true;
			}
		}
		return false;
	}

	/** Whether it comes back at the daily reset; a contract only comes back when it is done. */
	public boolean resetsDaily()
	{
		return this != CONTRACT;
	}

	/** Whether the account has earned this daily at all. */
	public boolean unlocked(Vars v)
	{
		switch (this)
		{
			case ZAFF:
				return done(v, VarbitID.VARROCK_DIARY_EASY_COMPLETE);
			case CROMPERTY:
				return done(v, VarbitID.ARDOUGNE_DIARY_MEDIUM_COMPLETE);
			case FLAX:
				return done(v, VarbitID.KANDARIN_DIARY_EASY_COMPLETE);
			case RANTZ:
				return done(v, VarbitID.WESTERN_DIARY_EASY_COMPLETE);
			case ROBIN:
				return done(v, VarbitID.MORYTANIA_DIARY_MEDIUM_COMPLETE);
			case THIRUS:
				return done(v, VarbitID.KOUREND_DIARY_MEDIUM_COMPLETE);
			case BERT:
				return v.varbit(VarbitID.IRONMAN) != 2 && v.varbit(VarbitID.HANDSAND_QUEST) >= SAND_QUEST_COMPLETE;
			case HERB_BOXES:
				return v.varbit(VarbitID.IRONMAN) == 0 && v.varp(VarPlayerID.NZONE_REWARDPOINTS) >= HERB_BOX_POINTS;
			case LUNDAIL:
				return done(v, VarbitID.WILDERNESS_DIARY_EASY_COMPLETE);
			case CONTRACT:
				return Contract.known(v);
			default:
				return false;
		}
	}

	/** Whether today's claim is still waiting. */
	public boolean claimable(Vars v)
	{
		if (!unlocked(v))
		{
			return false;
		}
		switch (this)
		{
			case ZAFF:
				return v.varbit(VarbitID.ZAFF_LAST_CLAIMED) == 0;
			case CROMPERTY:
				return v.varbit(VarbitID.ARDOUGNE_FREE_ESSENCE) == 0;
			case FLAX:
				return v.varbit(VarbitID.SEERS_FREE_FLAX) == 0;
			case RANTZ:
				return v.varbit(VarbitID.WESTERN_RANTZ_ARROWS) == 0;
			case ROBIN:
				return v.varbit(VarbitID.MORYTANIA_SLIME_CLAIMED) < amount(v);
			case THIRUS:
				return v.varbit(VarbitID.KOUREND_FREE_DYNAMITE) == 0;
			case BERT:
				return v.varbit(VarbitID.YANILLE_SAND_CLAIMED) == 0;
			case HERB_BOXES:
				return v.varbit(VarbitID.NZONE_HERBBOXES_PURCHASED) < HERB_BOX_MAX;
			case LUNDAIL:
				return v.varbit(VarbitID.LUNDAIL_LAST_CLAIMED) == 0;
			case CONTRACT:
				return Contract.complete(v) || Contract.type(v) == 0;
			default:
				return false;
		}
	}

	/** How many come today, or 0 when the amount is random. */
	public int amount(Vars v)
	{
		int t;
		switch (this)
		{
			case ZAFF:
				return pick(tier(v, VarbitID.VARROCK_DIARY_EASY_COMPLETE), 15, 30, 60, 120);
			case CROMPERTY:
				t = tier(v, VarbitID.ARDOUGNE_DIARY_EASY_COMPLETE);
				return pick(t, 0, 100, 150, 250);
			case FLAX:
				return pick(tier(v, VarbitID.KANDARIN_DIARY_EASY_COMPLETE), 30, 60, 120, 250);
			case RANTZ:
				return pick(tier(v, VarbitID.WESTERN_DIARY_EASY_COMPLETE), 25, 50, 100, 150);
			case ROBIN:
				t = tier(v, VarbitID.MORYTANIA_DIARY_EASY_COMPLETE);
				return Math.max(0, t - 1) * ROBIN_PER_TIER;
			case THIRUS:
				return pick(tier(v, VarbitID.KOUREND_DIARY_EASY_COMPLETE), 0, 20, 40, 80);
			case BERT:
				return BERT_SAND;
			case HERB_BOXES:
				int left = HERB_BOX_MAX - v.varbit(VarbitID.NZONE_HERBBOXES_PURCHASED);
				return Math.max(0, Math.min(left, v.varp(VarPlayerID.NZONE_REWARDPOINTS) / HERB_BOX_POINTS));
			default:
				return 0;
		}
	}

	/** Robin hands out a share at a time; how many are left today. */
	public int remaining(Vars v)
	{
		if (this == ROBIN)
		{
			return Math.max(0, amount(v) - v.varbit(VarbitID.MORYTANIA_SLIME_CLAIMED));
		}
		return amount(v);
	}

	/** What the board says comes back, such as "120 battlestaves". */
	public String reward(Vars v)
	{
		int n = remaining(v);
		switch (this)
		{
			case ZAFF:
				return n + " battlestaves for " + Format.coins((long) n * ZAFF_PRICE);
			case CROMPERTY:
				return n + " noted pure essence";
			case FLAX:
				return n + " flax spun into bowstrings";
			case RANTZ:
				return n + " ogre arrows";
			case ROBIN:
				return n + " bonemeal and buckets of slime";
			case THIRUS:
				return n + " dynamite";
			case BERT:
				return n + " buckets of sand";
			case HERB_BOXES:
				return n + " herb boxes for " + Format.number((long) n * HERB_BOX_POINTS) + " points";
			case LUNDAIL:
				return "A random handful of runes";
			case CONTRACT:
				int type = Contract.type(v);
				if (Contract.complete(v))
				{
					return "Done: hand it in for a seed pack and take the next";
				}
				if (type == 0 || Contract.cropName(type) == null)
				{
					return "No contract running: take one";
				}
				return Contract.cropName(type) + " in the guild's " + Contract.patch(type);
			default:
				return "";
		}
	}

	/** What the player needs to bring for it, or null. */
	public Need need(Vars v)
	{
		int n = remaining(v);
		switch (this)
		{
			case ZAFF:
				return new Need("coins", n * ZAFF_PRICE, ItemID.COINS);
			case FLAX:
				return new Need("flax", n, ItemID.FLAX, ItemID.FLAX + 1);
			case ROBIN:
				return new Need("bones", n, ROBIN_BONES);
			default:
				return null;
		}
	}

	/** Diary tiers done from easy upwards: easy is 1, elite 4. Each tier's varbit follows the last. */
	static int tier(Vars v, int easyVarbit)
	{
		int t = 0;
		for (int i = 0; i < 4; i++)
		{
			if (v.varbit(easyVarbit + i) == 1)
			{
				t = i + 1;
			}
		}
		return t;
	}

	private static int pick(int tier, int... byTier)
	{
		return tier <= 0 ? 0 : byTier[Math.min(tier, byTier.length) - 1];
	}

	private static boolean done(Vars v, int varbit)
	{
		return v.varbit(varbit) == 1;
	}
}

package com.codex.autopilot.core;

/** A daily's standing today: unlocked, claimable, what it gives and needs. */
public final class DailyState
{
	private final Daily daily;
	private final boolean unlocked;
	private final boolean claimable;
	private final String reward;
	private final Need need;

	public DailyState(Daily daily, boolean unlocked, boolean claimable, String reward, Need need)
	{
		this.daily = daily;
		this.unlocked = unlocked;
		this.claimable = claimable;
		this.reward = reward;
		this.need = need;
	}

	public static DailyState of(Daily d, Vars v)
	{
		boolean unlocked = d.unlocked(v);
		boolean claimable = unlocked && d.claimable(v);
		return new DailyState(d, unlocked, claimable, unlocked ? d.reward(v) : "", claimable ? d.need(v) : null);
	}

	public Daily getDaily()
	{
		return daily;
	}

	public boolean isUnlocked()
	{
		return unlocked;
	}

	public boolean isClaimable()
	{
		return claimable;
	}

	public String getReward()
	{
		return reward;
	}

	/** What to bring, or null. */
	public Need getNeed()
	{
		return need;
	}

	/** The state after the daily reset: claimable again if it was ever unlocked. */
	public DailyState afterReset()
	{
		return new DailyState(daily, unlocked, unlocked, reward, need);
	}
}

package com.codex.autopilot.core;

import java.util.Locale;

/**
 * Text for numbers and times, the way the whole Codex suite writes them: full numbers under
 * 10,000, whole thousands (k) under a million, millions (M) with one decimal and billions (B)
 * with two. Figures are cut down, never rounded up, so 999,999 reads 999k and not 1000k.
 */
public final class Format
{
	private Format()
	{
	}

	public static String number(long n)
	{
		if (n < 0)
		{
			return "-" + number(n == Long.MIN_VALUE ? Long.MAX_VALUE : -n);
		}
		if (n < 10_000)
		{
			return String.format(Locale.ROOT, "%,d", n);
		}
		if (n < 1_000_000)
		{
			return (n / 1000) + "k";
		}
		if (n < 1_000_000_000)
		{
			return String.format(Locale.ROOT, "%d.%dM", n / 1_000_000, (n % 1_000_000) / 100_000);
		}
		return String.format(Locale.ROOT, "%d.%02dB", n / 1_000_000_000, (n % 1_000_000_000) / 10_000_000);
	}

	/** "7,000 coins", "840k coins", "1.2M coins". */
	public static String coins(long n)
	{
		return number(n) + " coins";
	}

	/** "now", "4 min", "1 hr 20 min", "2 days 3 hr". */
	public static String duration(long seconds)
	{
		if (seconds <= 0)
		{
			return "now";
		}
		long mins = (seconds + 59) / 60;
		if (mins < 60)
		{
			return mins + " min";
		}
		long hrs = mins / 60;
		long rem = mins % 60;
		if (hrs < 24)
		{
			return rem == 0 ? hrs + " hr" : hrs + " hr " + rem + " min";
		}
		long days = hrs / 24;
		long h = hrs % 24;
		return (days == 1 ? "1 day" : days + " days") + (h == 0 ? "" : " " + h + " hr");
	}

	/** A short duration for tight spaces: "4m", "1h 20m", "2d 3h". */
	public static String shortDuration(long seconds)
	{
		if (seconds <= 0)
		{
			return "now";
		}
		long mins = (seconds + 59) / 60;
		if (mins < 60)
		{
			return mins + "m";
		}
		long hrs = mins / 60;
		long rem = mins % 60;
		if (hrs < 24)
		{
			return rem == 0 ? hrs + "h" : hrs + "h " + rem + "m";
		}
		long days = hrs / 24;
		long h = hrs % 24;
		return h == 0 ? days + "d" : days + "d " + h + "h";
	}

	/** "1 house", "4 houses". */
	public static String plural(long n, String one, String many)
	{
		return number(n) + " " + (n == 1 ? one : many);
	}
}

package com.codex.autopilot.core;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import net.runelite.api.gameval.ItemID;

/**
 * The goals pinned in Codex Navigator, read from the board it saves for companion plugins
 * ({@code codexnavigator/goalBoard}, per RS profile, fields only ever added):
 * {@code {"version":1,"focus":"quest:Dragon Slayer II","goals":[{"key","type","title","complete",
 * "progress","next","hoursLeft","skills","quests"}]}}. A board with a version above 1 has broken
 * its shape and is read as no board. Each unfinished goal with a next step becomes a step here.
 */
public final class GoalBoard
{
	public static final String GROUP = "codexnavigator";
	public static final String KEY = "goalBoard";

	/** One pinned goal, as far as Autopilot reads it. */
	public static final class Goal
	{
		private final String key;
		private final String type;
		private final String title;
		private final boolean complete;
		private final double progress;
		private final String next;
		private final double hoursLeft;

		public Goal(String key, String type, String title, boolean complete, double progress, String next, double hoursLeft)
		{
			this.key = key;
			this.type = type;
			this.title = title;
			this.complete = complete;
			this.progress = progress;
			this.next = next;
			this.hoursLeft = hoursLeft;
		}

		public String getKey()
		{
			return key;
		}

		public String getType()
		{
			return type;
		}

		public String getTitle()
		{
			return title;
		}

		public boolean isComplete()
		{
			return complete;
		}

		/** 0 to 1. */
		public double getProgress()
		{
			return progress;
		}

		/** Navigator's next step for it, such as "Start Monkey Madness II", or null. */
		public String getNext()
		{
			return next;
		}

		/** Navigator's estimate of the hours to finish, or 0 when it has none. */
		public double getHoursLeft()
		{
			return hoursLeft;
		}
	}

	private final String focus;
	private final List<Goal> goals;

	GoalBoard(String focus, List<Goal> goals)
	{
		this.focus = focus;
		this.goals = Collections.unmodifiableList(goals);
	}

	public static GoalBoard read(Profile profile, Gson gson)
	{
		return parse(gson, Profile.safe(profile, GROUP, KEY));
	}

	/** The board, or null when there is none, it is damaged, or it is a version this reader does not know. */
	public static GoalBoard parse(Gson gson, String json)
	{
		if (gson == null || json == null || json.trim().isEmpty())
		{
			return null;
		}
		try
		{
			JsonElement root = gson.fromJson(json, JsonElement.class);
			if (root == null || !root.isJsonObject())
			{
				return null;
			}
			JsonObject o = root.getAsJsonObject();
			long version = BankSnapshot.version(o);
			if (version > 1 || version < 0)
			{
				return null;
			}
			JsonElement list = o.get("goals");
			List<Goal> goals = new ArrayList<>();
			if (list != null && list.isJsonArray())
			{
				JsonArray a = list.getAsJsonArray();
				for (JsonElement e : a)
				{
					Goal g = goal(e);
					if (g != null)
					{
						goals.add(g);
					}
				}
			}
			else if (list != null && !list.isJsonNull())
			{
				return null;
			}
			return new GoalBoard(text(o.get("focus")), goals);
		}
		catch (RuntimeException e)
		{
			return null;
		}
	}

	private static Goal goal(JsonElement e)
	{
		if (e == null || !e.isJsonObject())
		{
			return null;
		}
		JsonObject o = e.getAsJsonObject();
		String key = text(o.get("key"));
		String title = text(o.get("title"));
		if (key == null || title == null)
		{
			return null;
		}
		JsonElement c = o.get("complete");
		boolean complete = c != null && c.isJsonPrimitive() && c.getAsJsonPrimitive().isBoolean() && c.getAsBoolean();
		return new Goal(key, text(o.get("type")), title, complete, clamp(real(o.get("progress")), 0, 1), text(o.get("next")),
			clamp(real(o.get("hoursLeft")), 0, 100_000));
	}

	private static String text(JsonElement e)
	{
		if (e == null || !e.isJsonPrimitive() || !e.getAsJsonPrimitive().isString())
		{
			return null;
		}
		String s = e.getAsString().trim();
		return s.isEmpty() ? null : s;
	}

	private static double real(JsonElement e)
	{
		if (e == null || !e.isJsonPrimitive() || !e.getAsJsonPrimitive().isNumber())
		{
			return 0;
		}
		double d = e.getAsDouble();
		return Double.isNaN(d) || Double.isInfinite(d) ? 0 : d;
	}

	private static double clamp(double d, double lo, double hi)
	{
		return Math.max(lo, Math.min(hi, d));
	}

	public String getFocus()
	{
		return focus;
	}

	public List<Goal> getGoals()
	{
		return goals;
	}

	/** Unfinished goals with a next step. */
	public int open()
	{
		int n = 0;
		for (Goal g : goals)
		{
			if (!g.isComplete() && g.getNext() != null)
			{
				n++;
			}
		}
		return n;
	}

	/** A step for each unfinished goal with a next step; the focused one in its own tier. */
	public List<Candidate> candidates()
	{
		List<Candidate> out = new ArrayList<>();
		for (Goal g : goals)
		{
			if (g.isComplete() || g.getNext() == null)
			{
				continue;
			}
			boolean focused = g.getKey().equals(focus);
			int minutes = (int) Math.max(15, Math.min(60, Math.round(g.getHoursLeft() * 60)));
			String pct = Math.round(g.getProgress() * 100) + "% done";
			String left = g.getHoursLeft() > 0 ? ", about " + hours(g.getHoursLeft()) + " to go" : "";
			String why = (focused ? "Your focus in Codex Navigator, " : "Pinned in Codex Navigator, ") + pct + left;
			// Sooner goals first: the less there is left, the more a step moves it.
			double urgency = 1.0 / (1.0 + g.getHoursLeft());
			out.add(new Candidate("goal:" + g.getKey(), focused ? Candidate.Kind.FOCUS_GOAL : Candidate.Kind.GOAL,
				focused ? Tier.FOCUS : Tier.GOAL, "Toward " + g.getTitle(), sentence(g.getNext()), why, null, minutes, urgency, 0, 1,
				icon(g.getType())));
		}
		return out;
	}

	static String hours(double h)
	{
		if (h < 1)
		{
			return Math.max(1, Math.round(h * 60)) + " min";
		}
		if (h < 10)
		{
			double r = Math.round(h * 2) / 2.0;
			return (r == Math.floor(r) ? String.valueOf((long) r) : String.format(Locale.ROOT, "%.1f", r)) + " hr";
		}
		return Math.round(h) + " hr";
	}

	/** Navigator writes steps as titles ("Start Shield of Arrav"); keep them as they are, first letter up. */
	static String sentence(String next)
	{
		return Character.toUpperCase(next.charAt(0)) + next.substring(1);
	}

	private static int icon(String type)
	{
		if (type == null)
		{
			return ItemID.SKILLCAPE_QP;
		}
		switch (type)
		{
			case "diary":
				return ItemID.ARDY_CAPE_ELITE;
			case "skill":
				return ItemID.SKILLCAPE_MAX;
			default:
				return ItemID.SKILLCAPE_QP;
		}
	}
}

package com.codex.autopilot.core;

import com.codex.autopilot.core.farming.Action;
import com.codex.autopilot.core.farming.CropState;
import com.codex.autopilot.core.farming.PatchKind;
import com.codex.autopilot.core.farming.PatchState;

/**
 * Predicts a patch or bird house from the last time it was seen. Farming ticks land on fixed
 * five-minute marks shifted by an account offset; the maths follows RuneLite's FarmingTracker.
 */
public final class Growth
{
	private Growth()
	{
	}

	/** The account's farming tick offset as RuneLite's Time Tracking learned it, or none. */
	public static final class Offset
	{
		public static final Offset NONE = new Offset(null, null);

		private final Integer minutes;
		private final Integer precision;

		public Offset(Integer minutes, Integer precision)
		{
			this.minutes = minutes;
			this.precision = precision;
		}

		long seconds(int tickRate)
		{
			if (minutes != null && precision != null && (precision >= tickRate || precision >= 40))
			{
				return (long) (minutes % tickRate) * 60;
			}
			return 0;
		}
	}

	private static final java.util.Map<PatchKind, Boolean> HEALTH_CHECK = new java.util.EnumMap<>(PatchKind.class);

	/** Whether a kind of patch has a check-health state once grown; Hespori, for one, goes straight to harvest. */
	static synchronized boolean hasHealthCheck(PatchKind kind)
	{
		return HEALTH_CHECK.computeIfAbsent(kind, k ->
		{
			for (int v = 0; v < 256; v++)
			{
				PatchState s = k.forVarbitValue(v);
				if (s != null && s.getAction() == Action.CHECK_HEALTH)
				{
					return true;
				}
			}
			return false;
		});
	}

	/** The unix second of the tick {@code ticks} after the one {@code time} falls in. */
	public static long tickTime(int tickRate, int ticks, long time, Offset offset)
	{
		long shift = offset.seconds(tickRate);
		long t = time + shift;
		long period = tickRate * 60L;
		long current = t - (t % period);
		return current + ticks * period - shift;
	}

	/** Reads a spot from what was last seen. */
	public static Reading read(Spot spot, Seen seen, long now, Offset offset)
	{
		if (seen == null)
		{
			return Reading.unseen(spot);
		}
		return spot.isBirdhouse() ? readBirdhouse(spot, seen, now) : readPatch(spot, seen, now, offset);
	}

	private static Reading readBirdhouse(Spot spot, Seen seen, long now)
	{
		Birdhouse.State state = Birdhouse.state(seen.getValue());
		switch (state)
		{
			case EMPTY:
				return Reading.birdhouse(spot, seen, Status.READY, state, 0, "Empty space: build a bird house");
			case BUILT:
				return Reading.birdhouse(spot, seen, Status.READY, state, 0, "Built: add seeds");
			case SEEDED:
				long full = seen.getTime() + Birdhouse.FILL_SECONDS;
				return now >= full
					? Reading.birdhouse(spot, seen, Status.READY, state, full, "Full: collect and reset")
					: Reading.birdhouse(spot, seen, Status.GROWING, state, full, "Filling");
			default:
				return Reading.unseen(spot);
		}
	}

	private static Reading readPatch(Spot spot, Seen seen, long now, Offset offset)
	{
		PatchState state = spot.getKind().forVarbitValue(seen.getValue());
		if (state == null)
		{
			return Reading.unseen(spot);
		}

		if (state.isScarecrow())
		{
			// Put there to keep birds off the allotments: nothing to do and nothing lost.
			return Reading.patch(spot, seen, Status.DONE, state, Action.GROWN, 0, "Scarecrow");
		}
		int stage = state.getStage();
		int stages = state.getStages();
		int tickRate = state.getProduce().getTickrate();
		if (state.getCropState() == CropState.HARVESTABLE)
		{
			tickRate = state.getProduce().getRegrowTickrate();
		}

		if (state.isEmpty())
		{
			// Weeds grow back on their own but nothing is lost: the patch is ready to plant.
			return Reading.patch(spot, seen, Status.READY, state, state.isClear() ? Action.PLANT : Action.RAKE, 0,
				state.isClear() ? "Clear soil: plant it" : "Weeds: rake and plant");
		}

		switch (state.getCropState())
		{
			case DISEASED:
				return Reading.patch(spot, seen, Status.READY, state, state.getAction(), 0, "Diseased: cure it");
			case DEAD:
				return Reading.patch(spot, seen, Status.READY, state, Action.CLEAR, 0,
					state.getStage() == 0 && state.getAction() == Action.CLEAR ? "Stump: clear and replant" : "Dead: clear and replant");
			case HARVESTABLE:
				if (state.getAction() == Action.CHOP)
				{
					return Reading.patch(spot, seen, Status.READY, state, Action.CHOP, 0, "Grown: clear and replant");
				}
				if (state.getAction() == Action.CLEAR)
				{
					return Reading.patch(spot, seen, Status.READY, state, Action.CLEAR, 0, "Stump: clear and replant");
				}
				if (spot.getKind() == PatchKind.CALQUAT && stage == 0)
				{
					return Reading.patch(spot, seen, Status.READY, state, Action.CLEAR, 0, "Picked: dig it up and replant");
				}
				if (tickRate > 0)
				{
					// Berries and spines grow back a stage at a time; stop when the bush is full.
					long seenTick = tickTime(tickRate, 0, seen.getTime(), offset);
					long nowTick = tickTime(tickRate, 0, now, offset);
					int delta = (int) ((nowTick - seenTick) / (tickRate * 60L));
					long full = tickTime(tickRate, stages - 1 - stage, seenTick, offset);
					return stage + delta >= stages - 1
						? Reading.patch(spot, seen, Status.READY, state, Action.HARVEST, full, "Full: ready to pick")
						: Reading.patch(spot, seen, Status.GROWING, state, Action.WAIT, full, "Regrowing");
				}
				return Reading.patch(spot, seen, Status.READY, state, Action.HARVEST, 0, "Ready to harvest");
			case GROWING:
			default:
				break;
		}

		if (state.getAction() == Action.GROWN)
		{
			return Reading.patch(spot, seen, Status.DONE, state, Action.GROWN, 0, "Fully grown");
		}
		if (state.getAction() == Action.CHECK_HEALTH)
		{
			return Reading.patch(spot, seen, Status.READY, state, Action.CHECK_HEALTH, 0, "Ready: check its health");
		}
		if (tickRate <= 0)
		{
			return Reading.patch(spot, seen, Status.GROWING, state, Action.WAIT, 0, "Growing");
		}

		long seenTick = tickTime(tickRate, 0, seen.getTime(), offset);
		long nowTick = tickTime(tickRate, 0, now, offset);
		int delta = (int) ((nowTick - seenTick) / (tickRate * 60L));
		long done = tickTime(tickRate, stages - 1 - stage, seenTick, offset);
		boolean anima = spot.getKind() == PatchKind.ANIMA;
		if (stage + delta >= stages - 1)
		{
			if (anima)
			{
				return Reading.patch(spot, seen, Status.READY, state, Action.CLEAR, done, "Withered: clear and replant");
			}
			Action next = hasHealthCheck(spot.getKind()) ? Action.CHECK_HEALTH : Action.HARVEST;
			return Reading.patch(spot, seen, Status.READY, state, next, done,
				next == Action.CHECK_HEALTH ? "Ready: check its health" : "Ready to harvest");
		}
		return Reading.patch(spot, seen, Status.GROWING, state, Action.WAIT, done, anima ? "Active" : "Growing");
	}
}

package com.codex.autopilot.core;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * Decides which heads-up notifications are new: once when a step starts going to waste, and once
 * when a chore trip becomes ready ("Bird houses are full"). The plugin only passes the text on to
 * RuneLite's notifier.
 *
 * <p>A step is told about once per state. It is told again only after it changes: going to waste
 * after it was only ready, or ready again after it was gone (done) for {@link #REARM} seconds, so
 * a step that flickers out for a reading or two is not repeated. The first look after a login or
 * account change only notes what is already there, so logging in does not set off a burst of old
 * news. Steps hidden by a snooze or quiet mode are noted but not announced.</p>
 */
public final class Heads
{
	/** How long a step must be gone before its return counts as new. */
	public static final long REARM = 5 * 60;

	/** One notification to send. */
	public static final class Notice
	{
		public final String key;
		public final Tier tier;
		public final String text;

		Notice(String key, Tier tier, String text)
		{
			this.key = key;
			this.tier = tier;
			this.text = text;
		}

		@Override
		public String toString()
		{
			return text;
		}
	}

	private final Map<String, Tier> told = new HashMap<>();
	private final Map<String, Long> goneSince = new HashMap<>();
	private boolean primed;

	/**
	 * Looks at every step offered now and returns what to announce. {@code visible} holds the keys
	 * the player can see (not snoozed, not held back by quiet mode); {@code waste} and {@code ready}
	 * are the player's toggles for each kind of notice.
	 */
	public synchronized List<Notice> observe(List<Candidate> all, Set<String> visible, long now, boolean waste, boolean ready)
	{
		List<Notice> out = new ArrayList<>();
		Map<String, Candidate> present = new HashMap<>();
		if (all != null)
		{
			for (Candidate c : all)
			{
				if (c != null && (c.getTier() == Tier.WASTING || c.getTier() == Tier.READY && c.getKind().isChore()))
				{
					present.put(c.getKey(), c);
				}
			}
		}
		for (Candidate c : present.values())
		{
			goneSince.remove(c.getKey());
			Tier before = told.get(c.getKey());
			boolean shown = visible == null || visible.contains(c.getKey());
			if (c.getTier() == Tier.WASTING)
			{
				if (before != Tier.WASTING && primed && waste && shown)
				{
					out.add(new Notice(c.getKey(), Tier.WASTING, wasteText(c)));
				}
				told.put(c.getKey(), Tier.WASTING);
			}
			else
			{
				if (before == null && primed && ready && shown)
				{
					out.add(new Notice(c.getKey(), Tier.READY, readyText(c)));
				}
				// Cured, but still ready: a later disease is news again; the trip being ready is not.
				told.put(c.getKey(), Tier.READY);
			}
		}
		for (Iterator<Map.Entry<String, Tier>> it = told.entrySet().iterator(); it.hasNext(); )
		{
			String key = it.next().getKey();
			if (present.containsKey(key))
			{
				continue;
			}
			long since = goneSince.computeIfAbsent(key, k -> now);
			if (now - since >= REARM || now < since)
			{
				it.remove();
				goneSince.remove(key);
			}
		}
		primed = true;
		return out;
	}

	/** Forgets everything told; the next look only takes note. For a login or another account. */
	public synchronized void reset()
	{
		told.clear();
		goneSince.clear();
		primed = false;
	}

	static String wasteText(Candidate c)
	{
		return "Going to waste: " + c.headline();
	}

	static String readyText(Candidate c)
	{
		if (c.getKind() == Candidate.Kind.BIRDHOUSE_RUN && "Birdhouse run".equals(c.getOver()))
		{
			return "Bird houses are full (" + c.getTitle() + ")";
		}
		return "Ready now: " + c.getOver() + " (" + c.getTitle() + ")";
	}
}

package com.codex.autopilot.core;

import com.codex.autopilot.core.farming.CropState;
import com.codex.autopilot.core.farming.PatchState;
import com.codex.autopilot.core.farming.Produce;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import net.runelite.api.gameval.ItemID;

/**
 * The herb run and the hops run, as one step each. Herb patches lead the herb run; the allotments
 * and flower patches beside them ride along ("Herb run: 7 ready, 2 diseased, 4 allotments"). A
 * diseased patch dies at its next growth tick, and a dead herb patch grows nothing until it is
 * cleared, so either puts the run among the steps going to waste.
 *
 * <p>Each crop weighs what it is worth to the run: an hour of a herb patch idle costs most of a
 * harvest, an hour of a flower patch costs three cheap ones, so flowers are weighted down and a
 * lone ready flower patch makes no step of its own.</p>
 */
final class HerbRun
{
	/** Every herb seed, so "herb seeds" counts any of them in the bank. */
	static final int[] HERB_SEEDS = {
		ItemID.GUAM_SEED, ItemID.MARRENTILL_SEED, ItemID.TARROMIN_SEED, ItemID.HARRALANDER_SEED, ItemID.RANARR_SEED,
		ItemID.TOADFLAX_SEED, ItemID.IRIT_SEED, ItemID.AVANTOE_SEED, ItemID.KWUARM_SEED, ItemID.HUASCA_SEED,
		ItemID.SNAPDRAGON_SEED, ItemID.CADANTINE_SEED, ItemID.LANTADYME_SEED, ItemID.DWARF_WEED_SEED, ItemID.TORSTOL_SEED,
	};
	static final int[] COMPOST = {ItemID.BUCKET_COMPOST, ItemID.BUCKET_SUPERCOMPOST, ItemID.BUCKET_ULTRACOMPOST};

	private HerbRun()
	{
	}

	/** What an hour idle costs, relative to a herb patch losing the same share of its cycle. */
	static double weight(Spot.Group g)
	{
		switch (g)
		{
			case HERBS:
				return 1.0;
			case HOPS:
				return 0.4;
			case ALLOTMENTS:
				return 0.3;
			default:
				return 0.15;
		}
	}

	/** "herb patch", "allotment", for sentences about one patch. */
	static String noun(Spot.Group g)
	{
		switch (g)
		{
			case HERBS:
				return "herb patch";
			case ALLOTMENTS:
				return "allotment";
			case FLOWERS:
				return "flower patch";
			default:
				return "hops patch";
		}
	}

	/** The town a spot is in: "Catherby" for "Catherby, north". */
	static String place(Spot s)
	{
		String l = s.getLabel();
		int comma = l.indexOf(',');
		return comma < 0 ? l : l.substring(0, comma);
	}

	/** The step for the herb or hops patches that are ready, or null when only flowers are. */
	static Candidate step(Candidate.Kind kind, List<Reading> list, List<Reading> soon, BankSnapshot bank, long now, Growth.Offset offset)
	{
		Spot.Group lead = kind == Candidate.Kind.HOPS_RUN ? Spot.Group.HOPS : null;
		if (lead == null)
		{
			for (Spot.Group g : Arrays.asList(Spot.Group.HERBS, Spot.Group.ALLOTMENTS, Spot.Group.FLOWERS))
			{
				if (lead == null && list.stream().anyMatch(r -> r.getSpot().getGroup() == g))
				{
					lead = g;
				}
			}
		}
		if (lead == null)
		{
			return null;
		}

		int ready = 0;
		int sick = 0;
		int dead = 0;
		int deadHerbs = 0;
		int allotments = 0;
		int flowers = 0;
		int replant = 0;
		int herbSeeds = 0;
		double urgency = 0;
		long idleSince = Long.MAX_VALUE;
		long dies = Long.MAX_VALUE;
		Reading first = null;
		Set<String> places = new LinkedHashSet<>();
		for (Reading r : list)
		{
			Spot s = r.getSpot();
			Spot.Group g = s.getGroup();
			places.add(place(s));
			double w = weight(g);
			urgency += w * 60.0 / Chores.cycleMinutes(s, r);
			PatchState p = r.getPatch();
			boolean diseased = Chores.diseased(r);
			boolean gone = p != null && p.getCropState() == CropState.DEAD;
			if (diseased)
			{
				long d = Chores.dies(r, offset);
				if (d > now)
				{
					sick++;
					if (d < dies)
					{
						dies = d;
						first = r;
					}
				}
				else
				{
					// Seen diseased a growth tick or more ago: dead by now unless it was cured.
					gone = true;
				}
			}
			if (gone)
			{
				dead++;
				if (g == Spot.Group.HERBS)
				{
					deadHerbs++;
				}
			}
			if (!diseased || gone)
			{
				replant++;
				if (g == Spot.Group.HERBS)
				{
					herbSeeds++;
				}
			}
			if (g == lead)
			{
				if (!diseased && !gone)
				{
					ready++;
				}
			}
			else if (g == Spot.Group.ALLOTMENTS)
			{
				allotments++;
			}
			else if (g == Spot.Group.FLOWERS)
			{
				flowers++;
			}
			if (!diseased && !gone && r.getReadyAt() > 0 && r.getReadyAt() <= now)
			{
				idleSince = Math.min(idleSince, r.getReadyAt());
			}
		}
		if (lead == Spot.Group.FLOWERS && sick == 0)
		{
			// Flowers alone are not worth a trip; they come along when the herbs are ready.
			return null;
		}

		String over = kind == Candidate.Kind.HOPS_RUN ? "Hops run"
			: lead == Spot.Group.HERBS ? "Herb run" : lead == Spot.Group.ALLOTMENTS ? "Allotment run" : "Flower patches";
		List<String> parts = new ArrayList<>();
		if (ready > 0)
		{
			parts.add(ready + " ready");
		}
		if (sick > 0)
		{
			parts.add(sick + " diseased");
		}
		if (dead > 0)
		{
			parts.add(dead + " dead");
		}
		if (allotments > 0)
		{
			parts.add(allotments == 1 ? "1 allotment" : allotments + " allotments");
		}
		if (flowers > 0)
		{
			parts.add(flowers == 1 ? "1 flower patch" : flowers + " flower patches");
		}
		String title = String.join(", ", parts);

		Tier tier = Tier.READY;
		long deadline = 0;
		String why;
		if (first != null)
		{
			tier = Tier.WASTING;
			deadline = dies;
			String in = Format.duration(dies - now);
			why = sick == 1
				? capital(noun(first.getSpot().getGroup())) + " at " + first.getSpot().getLabel() + " is diseased: cure it within " + in + " or it dies"
				: sick + " patches are diseased: the first dies in " + in + " unless cured";
			urgency += 60.0 / Math.max(5, (dies - now) / 60.0);
		}
		else if (deadHerbs > 0)
		{
			tier = Tier.WASTING;
			why = (deadHerbs == 1 ? "A herb patch has died" : deadHerbs + " herb patches have died")
				+ ": clear and replant, a dead patch grows nothing";
		}
		else if (dead > 0)
		{
			why = (dead == 1 ? "A patch has died" : dead + " patches have died") + ": clear and replant";
		}
		else if (idleSince != Long.MAX_VALUE && now - idleSince >= 60)
		{
			String idle = Format.duration(now - idleSince);
			why = lead == Spot.Group.HERBS ? "Grown for " + idle + ": every 80 min idle is a harvest lost"
				: "Grown for " + idle + ": pick and replant to keep them growing";
		}
		else
		{
			why = "Ready now: nothing grows there until you see to it";
		}
		if (!soon.isEmpty())
		{
			long next = Long.MAX_VALUE;
			for (Reading r : soon)
			{
				next = Math.min(next, r.getReadyAt());
			}
			why += "; " + soon.size() + " more ready in " + Format.duration(next - now);
		}

		// A stop per town, and a little longer for each extra patch there.
		int patches = list.size();
		int stops = places.size();
		int minutes = (int) Math.round(1 + stops * 2.5 + (patches - stops) * 0.75);

		String bring = Bring.line(needs(kind == Candidate.Kind.HERB_RUN ? herbSeeds : 0, replant, bank), bank);
		int item = produceItem(list, lead, kind == Candidate.Kind.HOPS_RUN ? ItemID.HAMMERSTONE_HOPS : ItemID.RANARR_WEED);
		return new Candidate("chores:" + kind.name().toLowerCase(), kind, tier, over, title, why, bring,
			minutes, urgency, deadline, patches, item);
	}

	/** Seeds for the herb patches and compost for every patch replanted; a filled bottomless bucket covers the compost. */
	static List<Need> needs(int seeds, int compost, BankSnapshot bank)
	{
		List<Need> out = new ArrayList<>();
		if (seeds > 0)
		{
			out.add(new Need(seeds == 1 ? "herb seed" : "herb seeds", seeds, HERB_SEEDS));
		}
		if (compost > 0)
		{
			if (bank != null && bank.count(ItemID.BOTTOMLESS_COMPOST_BUCKET_FILLED) > 0)
			{
				out.add(new Need("bottomless compost bucket", 1, ItemID.BOTTOMLESS_COMPOST_BUCKET_FILLED));
			}
			else
			{
				out.add(new Need("compost", compost, COMPOST));
			}
		}
		return out;
	}

	private static int produceItem(List<Reading> list, Spot.Group lead, int fallback)
	{
		for (Reading r : list)
		{
			Produce p = r.getProduce();
			if (r.getSpot().getGroup() == lead && p != null && p != Produce.ANYHERB && p.getItemId() > 0)
			{
				return p.getItemId();
			}
		}
		return fallback;
	}

	private static String capital(String s)
	{
		return s.isEmpty() ? s : Character.toUpperCase(s.charAt(0)) + s.substring(1);
	}
}

package com.codex.autopilot.core;

import java.time.Duration;
import java.time.Instant;
import java.time.temporal.ChronoUnit;

/**
 * The Kingdom of Miscellania. Approval (0 to 127) and the coffer live in varbits; away from the
 * kingdom both are estimated from the last values seen, the way RuneLite's Kingdom plugin does:
 * every day the coffer pays out a tenth of itself, capped at 50k (75k after Royal Trouble), and
 * approval falls by 2.5% (1% after Royal Trouble).
 */
public final class Kingdom
{
	public static final int MAX_APPROVAL = 127;
	public static final int MAX_COFFER = 7_500_000;
	public static final int[] REGIONS = {10044, 10300};

	private final int approval;
	private final int coffer;
	private final boolean royalTrouble;
	private final boolean estimated;

	public Kingdom(int approval, int coffer, boolean royalTrouble, boolean estimated)
	{
		this.approval = approval;
		this.coffer = coffer;
		this.royalTrouble = royalTrouble;
		this.estimated = estimated;
	}

	/** Today's kingdom, from a snapshot taken at {@code seenAt}. */
	public static Kingdom estimate(int approval, int coffer, long seenAt, long now, boolean royalTrouble)
	{
		int days = daysBetween(seenAt, now);
		int withdrawal = withdrawalCap(royalTrouble);
		int threshold = withdrawal * 10;
		int c = coffer;
		for (int i = 0; i < days && c > 0; i++)
		{
			c -= c > threshold ? withdrawal : c / 10;
		}
		float daily = royalTrouble ? 0.010f : 0.025f;
		int a = Math.max(0, approval - (int) (days * daily * MAX_APPROVAL));
		return new Kingdom(a, c, royalTrouble, days > 0);
	}

	public static int withdrawalCap(boolean royalTrouble)
	{
		return royalTrouble ? 75_000 : 50_000;
	}

	/** The coffer that keeps the full daily payout flowing: ten days of the cap. */
	public static int fullPayoutCoffer(boolean royalTrouble)
	{
		return withdrawalCap(royalTrouble) * 10;
	}

	static int daysBetween(long from, long to)
	{
		Instant a = Instant.ofEpochSecond(from).truncatedTo(ChronoUnit.DAYS);
		Instant b = Instant.ofEpochSecond(to).truncatedTo(ChronoUnit.DAYS);
		return (int) Math.max(0, Duration.between(a, b).toDays());
	}

	public int getApproval()
	{
		return approval;
	}

	public int approvalPercent()
	{
		return approval * 100 / MAX_APPROVAL;
	}

	public int getCoffer()
	{
		return coffer;
	}

	public boolean isRoyalTrouble()
	{
		return royalTrouble;
	}

	/** Whether the numbers are a guess carried forward from an earlier visit. */
	public boolean isEstimated()
	{
		return estimated;
	}

	/** Coins to deposit to reach the target, never past the coffer's cap. */
	public int topUp(int target)
	{
		int t = Math.min(MAX_COFFER, Math.max(0, target));
		return Math.max(0, t - coffer);
	}

	/** Whether a visit is due under the player's thresholds. */
	public boolean needsVisit(int approvalTargetPercent, int cofferTarget, int topUpSlack)
	{
		return approvalPercent() < approvalTargetPercent || topUp(cofferTarget) > topUpSlack;
	}

	/** Days until approval falls below a percentage, at the daily drop. */
	public int daysUntilApprovalBelow(int percent)
	{
		float daily = royalTrouble ? 0.010f : 0.025f;
		int perDay = Math.max(1, (int) (daily * MAX_APPROVAL));
		int floor = (percent * MAX_APPROVAL + 99) / 100;
		int above = approval - floor;
		return above < 0 ? 0 : above / perDay + 1;
	}
}

package com.codex.autopilot.core;

import java.time.Instant;
import java.time.format.DateTimeParseException;
import net.runelite.api.gameval.ItemID;

/**
 * The Kingdom of Miscellania as RuneLite's own Kingdom plugin last saved it
 * ({@code kingdomofmiscellania/lastChanged, approval, coffer}), carried forward to today the way
 * Codex Rounds does. Approval falls and the coffer pays out at each daily reset, so a kingdom
 * below its targets loses a little at every reset until someone visits.
 */
public final class KingdomWatch
{
	public static final String GROUP = "kingdomofmiscellania";
	public static final int DAY = 86_400;

	private KingdomWatch()
	{
	}

	/** Today's kingdom, or null when the Kingdom plugin has not saved one or what it saved is damaged. */
	public static Kingdom read(Profile profile, long now, boolean royalTrouble)
	{
		String changed = Profile.safe(profile, GROUP, "lastChanged");
		Integer approval = Chores.integer(Profile.safe(profile, GROUP, "approval"));
		Integer coffer = Chores.integer(Profile.safe(profile, GROUP, "coffer"));
		if (changed == null || approval == null || coffer == null)
		{
			return null;
		}
		long seenAt;
		try
		{
			seenAt = Instant.parse(changed.trim()).getEpochSecond();
		}
		catch (DateTimeParseException e)
		{
			return null;
		}
		if (seenAt <= 0 || seenAt > now + DAY)
		{
			return null;
		}
		int a = Math.max(0, Math.min(Kingdom.MAX_APPROVAL, approval));
		int c = Math.max(0, Math.min(Kingdom.MAX_COFFER, coffer));
		return Kingdom.estimate(a, c, seenAt, now, royalTrouble);
	}

	/** The next daily reset, midnight UTC. */
	public static long nextReset(long now)
	{
		return (Math.floorDiv(now, DAY) + 1) * DAY;
	}

	/** A visit step when the kingdom is under the player's targets, or null. */
	public static Candidate candidate(Kingdom k, Settings s, BankSnapshot bank, long now)
	{
		if (k == null)
		{
			return null;
		}
		int full = Kingdom.fullPayoutCoffer(k.isRoyalTrouble());
		int topUp = k.topUp(full);
		boolean lowApproval = k.approvalPercent() < s.getApprovalTarget();
		boolean lowCoffer = topUp > s.getCofferSlack();
		if (!lowApproval && !lowCoffer)
		{
			return null;
		}
		long reset = nextReset(now);
		boolean soon = reset - now <= s.getWasteHorizon();
		String drop = k.isRoyalTrouble() ? "1%" : "2.5%";
		String title;
		String why;
		if (lowApproval && lowCoffer)
		{
			title = k.approvalPercent() + "% approval, top up " + Format.number(topUp);
		}
		else if (lowApproval)
		{
			title = "Approval " + k.approvalPercent() + "%: help out";
		}
		else
		{
			title = "Top up the coffer by " + Format.number(topUp);
		}
		if (lowApproval)
		{
			why = "Approval drops " + drop + " at each reset" + (soon ? ", next in " + Format.duration(reset - now) : "")
				+ "; the haul shrinks with it";
		}
		else
		{
			why = "A coffer under " + Format.number(full) + " pays out less each day" + (soon ? "; next payout in " + Format.duration(reset - now) : "");
		}
		if (k.isEstimated())
		{
			why += " (estimated)";
		}
		double urgency = (lowApproval ? (s.getApprovalTarget() - k.approvalPercent()) / 100.0 : 0) + (lowCoffer ? topUp / (double) full : 0);
		// The value is lost at the reset, so it only counts as going to waste when the reset is near.
		return new Candidate("kingdom", Candidate.Kind.KINGDOM, soon ? Tier.WASTING : Tier.READY, "Miscellania", title, why,
			lowCoffer ? Bring.line(java.util.Collections.singletonList(new Need("coins", topUp, ItemID.COINS)), bank) : null, 6, 0.1 + urgency * 0.5, soon ? reset : 0, 1, ItemID.POH_TREASURE_TEAK);
	}
}

