package com.codex.autopilot.core;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonPrimitive;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;

/**
 * The player's own pace on each kind of chore, learned from runs they finished, so a step says
 * "~9 min (your pace)" instead of a guess. What is kept is minutes per stop (a house, a patch),
 * the last {@link #KEEP} runs of each kind; the median of them is trusted once there are
 * {@link #TRUST}. A step's time is then that median times the stops it covers.
 *
 * <p>Saved in Autopilot's own RS-profile config as
 * {@code {"version":1,"kinds":{"HERB_RUN":[1.9,2.1,1.7]}}}. A missing, damaged or newer value
 * reads as no pace learned, and any figure outside the sane range is dropped.</p>
 */
public final class Pace
{
	public static final String KEY = "paceV1";
	static final int VERSION = 1;
	/** Runs remembered per kind. */
	public static final int KEEP = 7;
	/** Runs needed before the learned time replaces the estimate. */
	public static final int TRUST = 3;
	/** Minutes per stop outside this range are a run interrupted or misread, not a pace. */
	public static final double MIN_STOP = 0.2;
	public static final double MAX_STOP = 15;

	private final Map<Candidate.Kind, List<Double>> samples = new EnumMap<>(Candidate.Kind.class);

	public static Pace empty()
	{
		return new Pace();
	}

	/** The saved pace, or an empty one when there is none or it cannot be read. Never null. */
	public static Pace parse(Gson gson, String json)
	{
		Pace p = new Pace();
		if (gson == null || json == null || json.trim().isEmpty())
		{
			return p;
		}
		try
		{
			JsonElement root = gson.fromJson(json, JsonElement.class);
			if (root == null || !root.isJsonObject())
			{
				return p;
			}
			JsonObject o = root.getAsJsonObject();
			JsonElement v = o.get("version");
			if (v == null || !v.isJsonPrimitive() || !v.getAsJsonPrimitive().isNumber() || v.getAsInt() != VERSION)
			{
				return p;
			}
			JsonElement kinds = o.get("kinds");
			if (kinds == null || !kinds.isJsonObject())
			{
				return p;
			}
			for (Map.Entry<String, JsonElement> e : kinds.getAsJsonObject().entrySet())
			{
				Candidate.Kind kind;
				try
				{
					kind = Candidate.Kind.valueOf(e.getKey());
				}
				catch (IllegalArgumentException ex)
				{
					continue;
				}
				if (!kind.isChore() || !e.getValue().isJsonArray())
				{
					continue;
				}
				for (JsonElement x : e.getValue().getAsJsonArray())
				{
					if (x != null && x.isJsonPrimitive() && x.getAsJsonPrimitive().isNumber())
					{
						p.add(kind, x.getAsDouble());
					}
				}
			}
		}
		catch (RuntimeException e)
		{
			return new Pace();
		}
		return p;
	}

	public synchronized String toJson(Gson gson)
	{
		JsonObject kinds = new JsonObject();
		for (Map.Entry<Candidate.Kind, List<Double>> e : samples.entrySet())
		{
			JsonArray a = new JsonArray();
			for (double d : e.getValue())
			{
				a.add(new JsonPrimitive(Math.round(d * 100) / 100.0));
			}
			kinds.add(e.getKey().name(), a);
		}
		JsonObject root = new JsonObject();
		root.addProperty("version", VERSION);
		root.add("kinds", kinds);
		return gson.toJson(root);
	}

	/** Records one finished run's minutes per stop; nonsense is ignored. Returns whether it was kept. */
	public synchronized boolean add(Candidate.Kind kind, double minutesPerStop)
	{
		if (kind == null || !kind.isChore() || Double.isNaN(minutesPerStop) || minutesPerStop < MIN_STOP || minutesPerStop > MAX_STOP)
		{
			return false;
		}
		List<Double> list = samples.computeIfAbsent(kind, k -> new ArrayList<>());
		list.add(minutesPerStop);
		while (list.size() > KEEP)
		{
			list.remove(0);
		}
		return true;
	}

	public synchronized int samples(Candidate.Kind kind)
	{
		List<Double> list = samples.get(kind);
		return list == null ? 0 : list.size();
	}

	/** Median minutes per stop once trusted, otherwise -1. */
	public synchronized double perStop(Candidate.Kind kind)
	{
		List<Double> list = samples.get(kind);
		if (list == null || list.size() < TRUST)
		{
			return -1;
		}
		List<Double> sorted = new ArrayList<>(list);
		Collections.sort(sorted);
		int n = sorted.size();
		return n % 2 == 1 ? sorted.get(n / 2) : (sorted.get(n / 2 - 1) + sorted.get(n / 2)) / 2;
	}

	/** The step with the learned time in place of the estimate, when the kind is trusted. */
	public Candidate apply(Candidate c)
	{
		if (c == null || !c.getKind().isChore())
		{
			return c;
		}
		double per = perStop(c.getKind());
		if (per <= 0)
		{
			return c;
		}
		return c.withPace((int) Math.max(1, Math.round(per * Math.max(1, c.getCount()))));
	}

	public synchronized boolean isEmpty()
	{
		return samples.isEmpty();
	}
}

package com.codex.autopilot.core;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;

/**
 * Times the player's chore runs, to teach {@link Pace}. A run is timed from its first stop done to
 * its last: the moment the step's count of ready stops first drops (a house reset, a patch
 * replanted) to the moment the step is gone because every stop is done. That span covers every
 * stop but the first, so it is divided by the stops less one to give minutes per stop.
 *
 * <p>Timing from the first stop done, rather than from when the step reached the top of the
 * queue, keeps a run the player left waiting for an hour from reading as an hour's work, and
 * needs no guess at where the player is walking. Only steps that were first in the queue while
 * being worked are learned from, and a run is dropped, not learned, when Autopilot loses sight
 * of it: no reading for {@link #GAP} seconds (logged out, plugin off), or the caller abandons it
 * because a setting changed. Runs of one stop cannot be timed this way and are not learned.</p>
 */
public final class PaceWatch
{
	/** Longer than this between readings and every run in progress is dropped. */
	public static final long GAP = 120;

	/** One finished run, ready to add to the pace. */
	public static final class Sample
	{
		public final Candidate.Kind kind;
		public final double minutesPerStop;

		Sample(Candidate.Kind kind, double minutesPerStop)
		{
			this.kind = kind;
			this.minutesPerStop = minutesPerStop;
		}

		@Override
		public String toString()
		{
			return kind + " " + minutesPerStop;
		}
	}

	private static final class Run
	{
		final Candidate.Kind kind;
		int count;
		int peak;
		long firstDone;
		boolean top;

		Run(Candidate.Kind kind, int count)
		{
			this.kind = kind;
			this.count = count;
			this.peak = count;
		}
	}

	private final Map<String, Run> runs = new HashMap<>();
	private long last;

	/**
	 * Looks at every chore step offered now (before snoozing or quiet mode hide any) and the key of
	 * the step shown first. Returns the runs that finished since the last look.
	 */
	public synchronized List<Sample> observe(List<Candidate> all, String topKey, long now)
	{
		List<Sample> out = new ArrayList<>();
		if (last > 0 && (now - last > GAP || now < last))
		{
			runs.clear();
		}
		last = now;
		Map<String, Candidate> chores = new HashMap<>();
		if (all != null)
		{
			for (Candidate c : all)
			{
				if (c != null && c.getKind().isChore())
				{
					chores.put(c.getKey(), c);
				}
			}
		}
		for (Iterator<Map.Entry<String, Run>> it = runs.entrySet().iterator(); it.hasNext(); )
		{
			Map.Entry<String, Run> e = it.next();
			if (chores.containsKey(e.getKey()))
			{
				continue;
			}
			Run r = e.getValue();
			it.remove();
			if (r.top && r.firstDone > 0 && r.peak >= 2)
			{
				double per = (now - r.firstDone) / 60.0 / (r.peak - 1);
				if (per >= Pace.MIN_STOP && per <= Pace.MAX_STOP)
				{
					out.add(new Sample(r.kind, per));
				}
			}
		}
		for (Candidate c : chores.values())
		{
			Run r = runs.get(c.getKey());
			if (r == null)
			{
				r = new Run(c.getKind(), c.getCount());
				runs.put(c.getKey(), r);
			}
			else
			{
				if (c.getCount() < r.count && r.firstDone == 0)
				{
					r.firstDone = now;
				}
				r.count = c.getCount();
				r.peak = Math.max(r.peak, c.getCount());
			}
			if (c.getKey().equals(topKey))
			{
				r.top = true;
			}
			else if (r.firstDone == 0)
			{
				// Led once but something else is first now, before any of it was done: it has to lead
				// again, or be led while worked, to count as the step the player was on.
				r.top = false;
			}
		}
		return out;
	}

	/** Drops every run in progress, as when the player logs out or a setting hides chores. */
	public synchronized void abandon()
	{
		runs.clear();
		last = 0;
	}

	synchronized int tracking()
	{
		return runs.size();
	}
}

package com.codex.autopilot.core;

import java.util.Collections;
import java.util.List;

/** The ranked steps, and what was held back. */
public final class Plan
{
	public static final Plan EMPTY = new Plan(Collections.emptyList(), 0, 0);

	private final List<Candidate> steps;
	private final int snoozed;
	private final int quiet;

	Plan(List<Candidate> steps, int snoozed, int quiet)
	{
		this.steps = Collections.unmodifiableList(steps);
		this.snoozed = snoozed;
		this.quiet = quiet;
	}

	public List<Candidate> getSteps()
	{
		return steps;
	}

	/** The one best thing to do now, or null. */
	public Candidate top()
	{
		return steps.isEmpty() ? null : steps.get(0);
	}

	/** Up to {@code n} steps after the top one. */
	public List<Candidate> after(int n)
	{
		if (steps.size() <= 1)
		{
			return Collections.emptyList();
		}
		return steps.subList(1, Math.min(steps.size(), 1 + n));
	}

	/** Steps snoozed and still asleep. */
	public int getSnoozed()
	{
		return snoozed;
	}

	/** Steps quiet mode is holding back. */
	public int getQuiet()
	{
		return quiet;
	}

	public long count(Tier tier)
	{
		return steps.stream().filter(c -> c.getTier() == tier).count();
	}

	public boolean isEmpty()
	{
		return steps.isEmpty();
	}
}

package com.codex.autopilot.core;

/**
 * Read access to this account's RuneLite profile config, so the core can be tested without a
 * client. The plugin backs it with {@code ConfigManager.getRSProfileConfiguration(group, key)}.
 * Autopilot only ever reads through it.
 */
public interface Profile
{
	Profile EMPTY = (group, key) -> null;

	/** The stored text, or null when there is none. */
	String get(String group, String key);

	/** Reads a value without letting anything thrown by the store get past. */
	static String safe(Profile p, String group, String key)
	{
		if (p == null)
		{
			return null;
		}
		try
		{
			return p.get(group, key);
		}
		catch (RuntimeException e)
		{
			return null;
		}
	}
}

package com.codex.autopilot.core;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

/**
 * Puts every candidate step in one order. The bands come first: what is about to go to waste,
 * then ready chores, then the focused goal's next step, then other goals. Inside a band, losses
 * due soonest lead, then the chores that save the most per minute spent (a full set of bird
 * houses and seaweed together beats one grown calquat), then the goals with least left.
 *
 * <p>With "goal first" on, ready chores that lose little by waiting (urgency under
 * {@link #GOAL_FIRST_BELOW}, such as grown trees, dailies with hours left or the kingdom) drop
 * below the focused goal. Skipped steps sink below everything, in the order they were skipped;
 * snoozed steps are left out until their hour is up.</p>
 */
public final class Ranker
{
	/** Chores losing less than this share of a cycle per hour give way to the goal when it comes first. */
	public static final double GOAL_FIRST_BELOW = 1.0;

	private Ranker()
	{
	}

	/** The band a step sorts in: 0 going to waste, 1 ready, 2 focus, 3 goals; chores giving way sit at 2.5. */
	static double band(Candidate c, Settings s)
	{
		switch (c.getTier())
		{
			case WASTING:
				return 0;
			case READY:
				return s.isGoalFirst() && c.getUrgency() < GOAL_FIRST_BELOW ? 2.5 : 1;
			case FOCUS:
				return 2;
			default:
				return 3;
		}
	}

	public static Plan rank(List<Candidate> candidates, Settings s, Session session, long now)
	{
		List<Candidate> keep = new ArrayList<>();
		int snoozed = 0;
		int quiet = 0;
		for (Candidate c : candidates)
		{
			if (c == null)
			{
				continue;
			}
			if (session != null && session.isSnoozed(c.getKey(), now))
			{
				snoozed++;
				continue;
			}
			if (s.isQuiet() && c.getTier() != Tier.WASTING)
			{
				quiet++;
				continue;
			}
			keep.add(c);
		}
		keep.sort(order(s, session));
		return new Plan(keep, snoozed, quiet);
	}

	static Comparator<Candidate> order(Settings s, Session session)
	{
		Comparator<Candidate> skipped = Comparator.comparingInt(c -> session == null ? 0 : session.skipOrder(c.getKey()));
		return skipped
			.thenComparingDouble(c -> band(c, s))
			.thenComparingLong(c -> c.getDeadline() > 0 ? c.getDeadline() : Long.MAX_VALUE)
			.thenComparing(Comparator.comparingDouble(Candidate::density).reversed())
			.thenComparing(Comparator.comparingInt(Candidate::getCount).reversed())
			.thenComparing(Candidate::getKey);
	}
}

package com.codex.autopilot.core;

import com.codex.autopilot.core.farming.Action;
import com.codex.autopilot.core.farming.PatchState;
import com.codex.autopilot.core.farming.Produce;

/** What a spot is doing now, predicted from the last time it was seen. */
public final class Reading
{
	private final Spot spot;
	private final Seen seen;
	private final Status status;
	private final PatchState patch;
	private final Birdhouse.State house;
	private final Action action;
	private final long readyAt;
	private final String summary;

	private Reading(Spot spot, Seen seen, Status status, PatchState patch, Birdhouse.State house, Action action, long readyAt, String summary)
	{
		this.spot = spot;
		this.seen = seen;
		this.status = status;
		this.patch = patch;
		this.house = house;
		this.action = action;
		this.readyAt = readyAt;
		this.summary = summary;
	}

	static Reading unseen(Spot spot)
	{
		return new Reading(spot, null, Status.UNSEEN, null, null, null, 0, "Not seen yet");
	}

	static Reading birdhouse(Spot spot, Seen seen, Status status, Birdhouse.State house, long readyAt, String summary)
	{
		return new Reading(spot, seen, status, null, house, null, readyAt, summary);
	}

	static Reading patch(Spot spot, Seen seen, Status status, PatchState patch, Action action, long readyAt, String summary)
	{
		return new Reading(spot, seen, status, patch, null, action, readyAt, summary);
	}

	/** The same reading under another status, such as switched off or locked. */
	public Reading as(Status s, String why)
	{
		return new Reading(spot, seen, s, patch, house, action, readyAt, why);
	}

	public Spot getSpot()
	{
		return spot;
	}

	public Seen getSeen()
	{
		return seen;
	}

	public Status getStatus()
	{
		return status;
	}

	/** The patch as last seen, or null for bird houses and unseen patches. */
	public PatchState getPatch()
	{
		return patch;
	}

	public Birdhouse.State getHouse()
	{
		return house;
	}

	/** The next thing to do there, for patches. */
	public Action getAction()
	{
		return action;
	}

	/** Unix second it is (or was) ready, or 0 when not known. */
	public long getReadyAt()
	{
		return readyAt;
	}

	public String getSummary()
	{
		return summary;
	}

	/** What is growing, or null. */
	public Produce getProduce()
	{
		return patch == null || patch.isEmpty() ? null : patch.getProduce();
	}

	public boolean isEmpty()
	{
		return patch != null && patch.isEmpty();
	}

	/** Seconds until ready, or 0 when ready or unknown. */
	public long secondsLeft(long now)
	{
		return status == Status.GROWING && readyAt > now ? readyAt - now : 0;
	}

	/** Whether a round should stop for it within the lookahead. */
	public boolean dueWithin(long now, long lookahead)
	{
		return status == Status.READY || status == Status.UNSEEN
			|| (status == Status.GROWING && readyAt > 0 && readyAt <= now + lookahead);
	}
}

package com.codex.autopilot.core;

import java.util.Objects;

/** A variable's value and the unix second it was first seen holding it. */
public final class Seen
{
	private final int value;
	private final long time;

	public Seen(int value, long time)
	{
		this.value = value;
		this.time = time;
	}

	public int getValue()
	{
		return value;
	}

	public long getTime()
	{
		return time;
	}

	/** Reads RuneLite's Time Tracking form, "value:unixtime". */
	public static Seen parse(String stored)
	{
		if (stored == null)
		{
			return null;
		}
		String[] parts = stored.split(":");
		if (parts.length != 2)
		{
			return null;
		}
		try
		{
			long time = Long.parseLong(parts[1]);
			return time > 0 ? new Seen(Integer.parseInt(parts[0]), time) : null;
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}

	@Override
	public boolean equals(Object o)
	{
		if (!(o instanceof Seen))
		{
			return false;
		}
		Seen s = (Seen) o;
		return value == s.value && time == s.time;
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(value, time);
	}

	@Override
	public String toString()
	{
		return value + ":" + time;
	}
}

package com.codex.autopilot.core;

import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.Map;

/**
 * What the player set aside this session: skipped steps sink below the rest, in the order they
 * were skipped; snoozed steps stay out of sight until their hour is up. Nothing here is saved.
 */
public final class Session
{
	public static final long SNOOZE = 3600;

	private final Map<String, Integer> skipped = new LinkedHashMap<>();
	private final Map<String, Long> snoozed = new HashMap<>();
	private int skips;

	public synchronized void skip(String key)
	{
		skipped.put(key, ++skips);
	}

	public synchronized void snooze(String key, long now)
	{
		snoozed.put(key, now + SNOOZE);
	}

	/** Brings everything set aside back. */
	public synchronized void clear()
	{
		skipped.clear();
		snoozed.clear();
	}

	/** 0 when not skipped, otherwise the order it was skipped in, from 1. */
	public synchronized int skipOrder(String key)
	{
		return skipped.getOrDefault(key, 0);
	}

	public synchronized boolean isSnoozed(String key, long now)
	{
		Long until = snoozed.get(key);
		if (until == null)
		{
			return false;
		}
		if (until <= now)
		{
			snoozed.remove(key);
			return false;
		}
		return true;
	}

	/** Unix second the snooze ends, or 0. */
	public synchronized long snoozedUntil(String key)
	{
		return snoozed.getOrDefault(key, 0L);
	}

	public synchronized boolean isEmpty()
	{
		return skipped.isEmpty() && snoozed.isEmpty();
	}
}

