	{
		if (isBirdhouse())
		{
			return "Bird house";
		}
		switch (kind)
		{
			case HARDWOOD_TREE:
				return "Hardwood";
			case SEAWEED:
				return "Seaweed";
			case CALQUAT:
				return "Calquat";
			case CELASTRUS:
				return "Celastrus";
			case REDWOOD:
				return "Redwood";
			case CRYSTAL_TREE:
				return "Crystal tree";
			case SPIRIT_TREE:
				return "Spirit tree";
			case CACTUS:
				return "Cactus";
			case BUSH:
				return "Bush";
			case MUSHROOM:
				return "Mushroom";
			case BELLADONNA:
				return "Belladonna";
			case ANIMA:
				return "Anima";
			case HESPORI:
				return "Hespori";
			case HERB:
				return "Herbs";
			case ALLOTMENT:
				return "Allotment";
			case FLOWER:
				return "Flowers";
			case HOPS:
				return "Hops";
			default:
				return kind.name();
		}
	}

	public Group getGroup()
	{
		return group;
	}

	/** The patch kind, or null for a bird house space. */
	public PatchKind getKind()
	{
		return kind;
	}

	public boolean isBirdhouse()
	{
		return kind == null;
	}

	/** Whether it is on Fossil Island or its seabed, where one trip covers it all. */
	public boolean isFossilIsland()
	{
		return isBirdhouse() || group == Group.SEAWEED || this == HARDWOOD_FOSSIL_E || this == HARDWOOD_FOSSIL_M || this == HARDWOOD_FOSSIL_W;
	}

	public int getVarbit()
	{
		return varbit;
	}

	public int getVarp()
	{
		return varp;
	}

	/** Where RuneLite's Time Tracking plugin keeps this spot, in its "timetracking" profile config. */
	public String timeTrackingKey()
	{
		return isBirdhouse() ? "birdhouse." + varp : regions[0] + "." + varbit;
	}
}

package com.codex.autopilot.core;

/** Where a chore stands on the board. */
public enum Status
{
	/** Something to do there now. */
	READY,
	/** Growing, filling or waiting, with a time it will be ready. */
	GROWING,
	/** Nothing to do: a grown spirit tree, a claimed daily. */
	DONE,
	/** Never seen, so the round should look. */
	UNSEEN,
	/** The account can't use it yet. */
	LOCKED,
	/** The player left it out. */
	OFF
}

package com.codex.autopilot.core;

/** How much a step matters right now, most pressing first. */
public enum Tier
{
	/** Loses something for good soon: a daily before the reset, a diseased patch, the kingdom's next drop. */
	WASTING("Going to waste"),
	/** Ready now and losing a little while it waits: full bird houses, grown trees, dailies to collect. */
	READY("Ready"),
	/** The next step toward the goal pinned in focus in Codex Navigator. */
	FOCUS("Your focus"),
	/** The next step toward another pinned goal. */
	GOAL("Goal");

	private final String label;

	Tier(String label)
	{
		this.label = label;
	}

	public String getLabel()
	{
		return label;
	}
}

