	private final String name;
	private final PatchKind kind;
	private final int itemId;
	private final int tickrate;
	private final int stages;
	private final int regrowTickrate;
	private final int harvestStages;
	private final int seedId;
	private final int level;
	/** Item, amount pairs the gardener takes to protect the crop, empty when it cannot be protected. */
	private final int[] payment;

	Produce(String name, PatchKind kind, int itemId, int tickrate, int stages, int regrowTickrate, int harvestStages,
		int seedId, int level, int... payment)
	{
		this.name = name;
		this.kind = kind;
		this.itemId = itemId;
		this.tickrate = tickrate;
		this.stages = stages;
		this.regrowTickrate = regrowTickrate;
		this.harvestStages = harvestStages;
		this.seedId = seedId;
		this.level = level;
		this.payment = payment;
	}

	public String getName()
	{
		return name;
	}

	public PatchKind getKind()
	{
		return kind;
	}

	/** The item the crop is shown with. */
	public int getItemId()
	{
		return itemId;
	}

	/** Minutes per growth tick. */
	public int getTickrate()
	{
		return tickrate;
	}

	/** States while growing, typically growth ticks plus one. */
	public int getStages()
	{
		return stages;
	}

	/** Minutes for the produce to regrow once picked, or zero when it does not. */
	public int getRegrowTickrate()
	{
		return regrowTickrate;
	}

	/** States while harvestable: the lives of the patch. */
	public int getHarvestStages()
	{
		return harvestStages;
	}

	/** What is planted: a seed, spore or sapling. */
	public int getSeedId()
	{
		return seedId;
	}

	/** Farming level needed to plant it. */
	public int getLevel()
	{
		return level;
	}

	public int[] getPayment()
	{
		return payment.clone();
	}

	public boolean isProtectable()
	{
		return payment.length > 0;
	}

	/** Minutes from planting to fully grown. */
	public int growMinutes()
	{
		return tickrate * Math.max(0, stages - 1);
	}

	/** Every crop that grows in a kind of patch, lowest level first. */
	public static java.util.List<Produce> forKind(PatchKind kind)
	{
		java.util.List<Produce> list = new java.util.ArrayList<>();
		for (Produce p : values())
		{
			if (p.kind == kind)
			{
				list.add(p);
			}
		}
		list.sort(java.util.Comparator.comparingInt(Produce::getLevel));
		return list;
	}
}

package com.codex.autopilot.overlay;

import com.codex.autopilot.core.Bring;
import com.codex.autopilot.core.Candidate;
import com.codex.autopilot.ui.Glyph;
import com.codex.autopilot.ui.Sigil;
import com.codex.autopilot.ui.StepCard;
import com.codex.autopilot.ui.Theme;
import com.codex.autopilot.ui.Ui;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.Shape;
import java.awt.geom.RoundRectangle2D;
import java.util.ArrayList;
import java.util.List;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * The plaque in the game view: the one best next step for the account in gilt letters, what
 * kind of step it is and how long it takes, the reason in a line or two and what to bring. A
 * stripe down its left edge takes the step's colour: ember when something is about to go to
 * waste, green for a ready chore, teal for the focused goal.
 */
public class StepPlaque extends Overlay
{
	private static final int PAD = 8;
	private static final int MIN_WIDTH = 200;
	private static final int MAX_WIDTH = 270;

	private volatile Candidate shown;

	public StepPlaque()
	{
		setPosition(OverlayPosition.TOP_LEFT);
		setPriority(PRIORITY_HIGH);
	}

	/** The step to show; null hides the plaque. */
	public void show(Candidate c)
	{
		shown = c;
	}

	public Candidate getShown()
	{
		return shown;
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		Candidate c = shown;
		if (c == null)
		{
			return null;
		}
		Theme.smooth(g);
		g.setFont(Theme.title());
		FontMetrics bold = g.getFontMetrics();
		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();

		Color tint = Theme.tier(c.getTier());
		int icon = 18;
		int textX = PAD + 4 + icon + 8;
		String over = "NEXT: " + c.getOver().toUpperCase();
		String note = StepCard.paceNote(c);
		String time = StepCard.minutes(c) + (note == null ? "" : " (" + note + ")");
		int want = textX + Math.max(bold.stringWidth(c.getTitle()), Math.max(small.stringWidth(c.getWhy()) / 2 + 20,
			small.stringWidth(over) + small.stringWidth(time) + 12)) + PAD;
		int width = Math.max(MIN_WIDTH, Math.min(MAX_WIDTH, want));
		int room = width - textX - PAD;
		String[] titleLines = wrap(c.getTitle(), bold, room, 2);
		String[] why = wrap(c.getWhy(), small, room, 3);
		String[] bring = wrap(c.getBring(), small, room, 2);
		int height = PAD + small.getHeight() + titleLines.length * bold.getHeight() + why.length * small.getHeight()
			+ bring.length * small.getHeight() + 8;

		Shape shape = new RoundRectangle2D.Float(0.5f, 0.5f, width - 1, height - 1, 10, 10);
		g.setPaint(new GradientPaint(0, 0, Theme.alpha(Theme.CARD_TOP, 238), 0, height, Theme.alpha(Theme.INK_DEEP, 238)));
		g.fill(shape);

		// The tier stripe, inside the rounded edge.
		g.setClip(shape);
		g.setPaint(new GradientPaint(0, 0, tint, 0, height, Theme.alpha(tint, 80)));
		g.fillRect(0, 0, 3, height);
		g.setClip(null);

		g.setColor(Theme.alpha(Theme.GOLD, 150));
		g.draw(shape);
		g.setColor(Theme.alpha(Color.WHITE, 14));
		g.drawLine(6, 1, width - 6, 1);

		Sigil.paint(g, PAD + 4, PAD + 1, icon);
		Glyph.paint(g, c.getKind(), PAD + 4 + 3, PAD + icon + 6, icon - 6, tint);

		int y = PAD + small.getAscent();
		g.setFont(Theme.small());
		int tw = small.stringWidth(time);
		Ui.shadowed(g, Ui.clip(over, small, room - tw - 8), textX, y, Theme.TEXT_MUTED);
		Ui.shadowed(g, time, width - PAD - tw, y, Theme.GOLD_DIM);
		g.setFont(Theme.title());
		for (String line : titleLines)
		{
			y += bold.getHeight();
			Ui.shadowed(g, line, textX, y, Theme.GOLD_BRIGHT);
		}
		g.setFont(Theme.small());
		for (String line : why)
		{
			y += small.getHeight();
			Ui.shadowed(g, line, textX, y, Theme.TEXT);
		}
		for (String line : bring)
		{
			y += small.getHeight();
			Ui.shadowed(g, line, textX, y, Bring.isShort(c.getBring()) ? Theme.EMBER : Theme.TEAL);
		}
		return new Dimension(width, height);
	}

	static String[] wrap(String text, FontMetrics fm, int width, int maxLines)
	{
		if (text == null || text.isEmpty())
		{
			return new String[0];
		}
		List<String> out = new ArrayList<>();
		StringBuilder line = new StringBuilder();
		String[] words = text.split(" ");
		int i = 0;
		for (; i < words.length; i++)
		{
			String word = words[i];
			String trial = line.length() == 0 ? word : line + " " + word;
			if (fm.stringWidth(trial) > width && line.length() > 0)
			{
				out.add(line.toString());
				line = new StringBuilder(word);
				if (out.size() == maxLines)
				{
					break;
				}
			}
			else
			{
				line = new StringBuilder(trial);
			}
		}
		if (out.size() < maxLines)
		{
			if (line.length() > 0)
			{
				out.add(Ui.clip(line.toString(), fm, width));
			}
		}
		else
		{
			// Ran out of lines with words to spare: end the last one with an ellipsis.
			out.set(maxLines - 1, Ui.clip(out.get(maxLines - 1) + " ...", fm, width));
		}
		return out.toArray(new String[0]);
	}
}

package com.codex.autopilot.ui;

import com.codex.autopilot.core.Budget;

/** What the panel's buttons ask the plugin to do. */
public interface Actions
{
	/** Move a step below the rest for this session. */
	void skip(String key);

	/** Hide a step for an hour. */
	void snooze(String key);

	/** Plan for this much time, from the selector at the top of the panel. */
	void budget(Budget budget);

	/** Bring back everything skipped or snoozed. */
	void restore();
}

package com.codex.autopilot.ui;

import java.awt.Component;
import javax.swing.Timer;

/** Eases a value toward its target on the Swing thread so rings and bars fill instead of jumping. */
final class Animator
{
	private static final int FRAME_MS = 16;
	private static final double EASE = 0.18;

	private final Component owner;
	private final Timer timer;
	private double value;
	private double target;

	Animator(Component owner)
	{
		this.owner = owner;
		this.timer = new Timer(FRAME_MS, e -> step());
	}

	double get()
	{
		return value;
	}

	void set(double newTarget, boolean animate)
	{
		target = newTarget;
		if (!animate || !owner.isShowing())
		{
			value = newTarget;
			timer.stop();
			owner.repaint();
			return;
		}
		if (!timer.isRunning())
		{
			timer.start();
		}
	}

	private void step()
	{
		value += (target - value) * EASE;
		if (Math.abs(target - value) < 0.002 || !owner.isShowing())
		{
			value = target;
			timer.stop();
		}
		owner.repaint();
	}
}

package com.codex.autopilot.ui;

import com.codex.autopilot.core.Budget;
import com.codex.autopilot.core.Candidate;
import com.codex.autopilot.core.Plan;
import com.codex.autopilot.core.Tier;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.GridLayout;
import java.util.List;
import javax.swing.JComponent;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.ScrollPaneConstants;
import net.runelite.client.ui.PluginPanel;

/**
 * The Autopilot side panel: the crest with how many steps are waiting, the one best thing to do
 * now, the five after it with why each is there, and the sources it read them from.
 */
public class AutopilotPanel extends PluginPanel
{
	static final int WIDTH = 200;
	static final int AFTER = 5;

	private final Actions actions;
	private final Crest crest = new Crest();
	private final JScrollPane scroll = new JScrollPane();
	private View view = View.empty();

	public AutopilotPanel(Actions actions)
	{
		super(false);
		this.actions = actions;
		setLayout(new BorderLayout());
		setBackground(Theme.INK);
		add(crest, BorderLayout.NORTH);
		scroll.setBorder(null);
		scroll.setOpaque(false);
		scroll.getViewport().setOpaque(false);
		scroll.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		scroll.getVerticalScrollBar().setUnitIncrement(16);
		scroll.getVerticalScrollBar().setPreferredSize(new Dimension(8, 0));
		add(scroll, BorderLayout.CENTER);
		rebuild();
	}

	/** Called on the Swing thread whenever anything shown changes. */
	public void update(View view)
	{
		this.view = view;
		rebuild();
	}

	private void rebuild()
	{
		updateCrest();
		int y = scroll.getVerticalScrollBar().getValue();
		scroll.setViewportView(build());
		scroll.getVerticalScrollBar().setValue(y);
		revalidate();
		repaint();
	}

	private void updateCrest()
	{
		if (!view.known)
		{
			crest.update("ON YOUR ACCOUNT", null, "step", "steps", "Log in to read your account", null, Theme.TEXT_MUTED, Theme.GOLD);
			return;
		}
		Plan p = view.plan;
		int n = p.getSteps().size();
		if (view.steppingAside())
		{
			crest.update("STEPPING ASIDE", n, "step", "steps", view.activity.getWhere(), null, Theme.TEAL, Theme.GOLD_DIM);
			return;
		}
		long wasting = p.count(Tier.WASTING);
		long ready = p.count(Tier.READY);
		String status;
		Color color;
		if (wasting > 0)
		{
			status = wasting + " going to waste soon";
			color = Theme.EMBER;
		}
		else if (ready > 0)
		{
			status = ready + (ready == 1 ? " chore ready now" : " chores ready now");
			color = Theme.GREEN;
		}
		else if (p.count(Tier.FOCUS) > 0)
		{
			status = "Clear for your goal";
			color = Theme.TEAL;
		}
		else
		{
			status = n == 0 ? "All caught up" : "Goals waiting";
			color = Theme.TEXT_MUTED;
		}
		crest.update(view.quiet ? "QUIET MODE" : "ON YOUR ACCOUNT", n, "step", "steps", status, null, color,
			wasting > 0 ? Theme.EMBER : Theme.GOLD);
	}

	private StackPanel build()
	{
		StackPanel list = new StackPanel(6, 8);
		if (!view.known)
		{
			list.add(note("Log in and Autopilot reads your bird houses, patches, dailies and kingdom, and the goals you pinned in "
				+ "Codex Navigator, then keeps the one best next step in view."));
			sources(list);
			return list;
		}

		Plan p = view.plan;
		Candidate top = p.top();
		if (!view.steppingAside())
		{
			list.add(budgetBar());
		}
		if (view.steppingAside())
		{
			list.add(new SectionHeader("Stepping aside"));
			list.add(aside());
			if (top != null)
			{
				list.space(2);
				list.add(new SectionHeader("When you're done", p.getSteps().size() == 1 ? "1 step" : p.getSteps().size() + " steps"));
				list.add(StepCard.lead(top, null, WIDTH - 30, true));
			}
		}
		else if (top == null)
		{
			list.add(new SectionHeader("Do this now"));
			list.add(caughtUp());
		}
		else if (view.budgeted() && !view.fit.isEmpty())
		{
			budgeted(list);
		}
		else
		{
			if (view.budgeted())
			{
				list.add(note("Nothing fits in " + view.budget + ": the quickest step takes ~" + view.fit.getShortest()
					+ " min. Here is the best one anyway."));
			}
			list.add(new SectionHeader("Do this now", top.getTier() == Tier.WASTING && top.getDeadline() > 0 ? "before it's lost" : null));
			list.add(StepCard.lead(top, actions, WIDTH - 30, false));
			List<Candidate> after = p.after(AFTER);
			if (!after.isEmpty())
			{
				list.space(2);
				int more = p.getSteps().size() - 1;
				list.add(new SectionHeader("Then", more == 1 ? "1 more" : more + " more"));
				int i = 2;
				for (Candidate c : after)
				{
					list.add(StepCard.row(i++, c, actions, WIDTH - 30));
				}
			}
		}

		if (view.skipped || p.getSnoozed() > 0 || p.getQuiet() > 0)
		{
			list.space(2);
			list.add(heldBack(p));
		}
		sources(list);
		return list;
	}

	/** The steps that fit the time the player has, in the order to do them. */
	private void budgeted(StackPanel list)
	{
		Budget.Fit fit = view.fit;
		List<Candidate> steps = fit.getSteps();
		Candidate first = steps.get(0);
		list.add(new SectionHeader("In your " + view.budget, "~" + fit.getTotal() + " min"));
		list.add(StepCard.lead(first, actions, WIDTH - 30, false));
		if (steps.size() > 1)
		{
			list.space(2);
			list.add(new SectionHeader("Then", steps.size() - 1 == 1 ? "1 more" : steps.size() - 1 + " more"));
			for (int i = 1; i < steps.size(); i++)
			{
				list.add(StepCard.row(i + 1, steps.get(i), actions, WIDTH - 30));
			}
		}
		if (fit.getLeft() > 0)
		{
			list.space(2);
			list.add(note((fit.getLeft() == 1 ? "1 more step waits" : fit.getLeft() + " more steps wait") + " for when you have longer."));
		}
	}

	/** "I have 15 / 30 / 60 / Any": what the plan has to fit in. */
	private JComponent budgetBar()
	{
		JPanel bar = new JPanel(new BorderLayout(6, 0));
		bar.setOpaque(false);
		javax.swing.JLabel label = new javax.swing.JLabel("I have");
		label.setFont(Theme.small());
		label.setForeground(Theme.GOLD);
		bar.add(label, BorderLayout.WEST);
		JPanel buttons = new JPanel(new GridLayout(1, 0, 4, 0));
		buttons.setOpaque(false);
		for (Budget b : new Budget[]{Budget.MIN_15, Budget.MIN_30, Budget.MIN_60, Budget.NONE})
		{
			String text = b == Budget.NONE ? "Any" : b.getMinutes() + "m";
			buttons.add(new CodexButton(text, b == view.budget, 18, () -> actions.budget(b)));
		}
		bar.add(buttons, BorderLayout.CENTER);
		return bar;
	}

	private JComponent aside()
	{
		Card card = new Card(new BorderLayout(0, 4)).accent(Theme.TEAL);
		StackPanel body = new StackPanel(3, 0);
		String who = view.minigamePilot ? "Minigame Pilot has this" : view.activity.getLabel() + " has your attention";
		body.add(Ui.wrapped(who, Theme.title(), Theme.GOLD_BRIGHT, WIDTH - 30));
		body.add(Ui.wrapped(view.activity.getWhere() + ". Autopilot stays quiet here and picks up again when you leave.",
			Theme.small(), Theme.TEXT, WIDTH - 30));
		card.add(body, BorderLayout.CENTER);
		return card;
	}

	private JComponent caughtUp()
	{
		Card card = new Card(new BorderLayout(0, 4)).accent(Theme.GOLD_DIM);
		StackPanel body = new StackPanel(3, 0);
		body.add(Ui.wrapped(view.quiet ? "Nothing going to waste" : "All caught up", Theme.title(), Theme.GOLD_BRIGHT, WIDTH - 30));
		String detail = view.nextUp != null ? view.nextUp + "." : "Nothing is ready and no goal has a next step.";
		if (!view.quiet && view.plan.getSnoozed() == 0)
		{
			detail += " Pin a goal in Codex Navigator and its next step shows here.";
		}
		body.add(Ui.wrapped(detail, Theme.small(), Theme.TEXT, WIDTH - 30));
		card.add(body, BorderLayout.CENTER);
		return card;
	}

	private JComponent heldBack(Plan p)
	{
		StringBuilder sb = new StringBuilder();
		if (p.getQuiet() > 0)
		{
			sb.append("Quiet mode holds back ").append(p.getQuiet()).append(p.getQuiet() == 1 ? " step" : " steps").append(". ");
		}
		if (p.getSnoozed() > 0)
		{
			sb.append(p.getSnoozed()).append(" snoozed. ");
		}
		if (view.skipped)
		{
			sb.append("Skipped steps wait at the end. ");
		}
		Card card = new Card(new BorderLayout(0, 6));
		card.add(Ui.wrapped(sb.toString().trim(), Theme.small(), Theme.TEXT_MUTED, WIDTH - 30), BorderLayout.CENTER);
		if (view.skipped || p.getSnoozed() > 0)
		{
			JPanel bar = new JPanel(new FlowLayout(FlowLayout.LEFT, 0, 0));
			bar.setOpaque(false);
			bar.add(new CodexButton("Bring them back", false, 20, actions::restore));
			card.add(bar, BorderLayout.SOUTH);
		}
		return card;
	}

	private void sources(StackPanel list)
	{
		if (view.sources.isEmpty())
		{
			return;
		}
		list.space(2);
		list.add(new SectionHeader("Reading from"));
		JPanel grid = new JPanel(new GridLayout(0, 2, 6, 6));
		grid.setOpaque(false);
		for (View.Source s : view.sources)
		{
			grid.add(new StatTile(s.label, s.value, s.live));
		}
		list.add(grid);
	}

	private static JComponent note(String text)
	{
		Card card = new Card(new BorderLayout());
		card.add(Ui.wrapped(text, Theme.small(), Theme.TEXT_MUTED, WIDTH - 30), BorderLayout.CENTER);
		return card;
	}
}

package com.codex.autopilot.ui;

import java.awt.Color;
import java.awt.Cursor;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.LayoutManager;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;

/**
 * A rounded, softly lit surface. Optionally clickable, with a hover lift and an
 * accent stripe down the left edge.
 */
public class Card extends JPanel
{
	private Color accent;
	private boolean hover;
	private boolean highlighted;
	private Runnable onClick;

	public Card(LayoutManager layout)
	{
		super(layout);
		setOpaque(false);
		setBorder(new EmptyBorder(8, 10, 8, 10));
	}

	public Card accent(Color color)
	{
		accent = color;
		repaint();
		return this;
	}

	/** A brighter rim for the card that matters most on screen. */
	public Card highlighted(boolean value)
	{
		highlighted = value;
		repaint();
		return this;
	}

	public Card onClick(Runnable action)
	{
		onClick = action;
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		MouseAdapter adapter = new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				hover = true;
				repaint();
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				// Children forward their events here, so only clear hover when the pointer has really left.
				if (!contains(SwingUtilities.convertPoint(e.getComponent(), e.getPoint(), Card.this)))
				{
					hover = false;
					repaint();
				}
			}

			@Override
			public void mouseReleased(MouseEvent e)
			{
				if (SwingUtilities.isLeftMouseButton(e) && onClick != null
					&& contains(SwingUtilities.convertPoint(e.getComponent(), e.getPoint(), Card.this)))
				{
					onClick.run();
				}
			}
		};
		addMouseListener(adapter);
		Ui.forwardMouse(this, adapter);
		return this;
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		RoundRectangle2D shape = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1, h - 1, Theme.RADIUS, Theme.RADIUS);

		Color top = hover ? Theme.CARD_HOVER : Theme.CARD_TOP;
		Color bottom = hover ? Theme.mix(Theme.CARD_HOVER, Theme.CARD, 0.5) : Theme.CARD;
		g.setPaint(new GradientPaint(0, 0, top, 0, h, bottom));
		g.fill(shape);

		if (accent != null)
		{
			g.setClip(shape);
			g.setPaint(new GradientPaint(0, 0, accent, 0, h, Theme.alpha(accent, 90)));
			g.fillRect(0, 0, 3, h);
			g.setClip(null);
		}

		Color rim = highlighted ? Theme.alpha(Theme.GOLD, 150) : hover ? Theme.alpha(Theme.GOLD, 90) : Theme.STROKE_SOFT;
		g.setColor(rim);
		g.draw(shape);

		// A one pixel sheen along the top edge, like light on vellum.
		g.setColor(Theme.alpha(Color.WHITE, hover ? 22 : 12));
		g.drawLine(Theme.RADIUS / 2, 1, w - Theme.RADIUS / 2, 1);
		g.dispose();
		super.paintComponent(graphics);
	}
}

package com.codex.autopilot.ui;

import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JComponent;

/** A gilt-edged button; the primary style is filled, the quiet style is just an outline. */
public class CodexButton extends JComponent
{
	private final String text;
	private final boolean primary;
	private boolean hover;
	private boolean pressed;

	public CodexButton(String text, boolean primary, Runnable action)
	{
		this(text, primary, 22, action);
	}

	/** A button of a given height; 18 suits a row, 22 a card. */
	public CodexButton(String text, boolean primary, int height, Runnable action)
	{
		this.text = text;
		this.primary = primary;
		setFont(Theme.small());
		setOpaque(false);
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		FontMetrics fm = getFontMetrics(getFont());
		Dimension d = new Dimension(fm.stringWidth(text) + (height < 22 ? 14 : 20), height);
		setPreferredSize(d);
		setMinimumSize(d);
		setMaximumSize(d);
		addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				hover = true;
				repaint();
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				hover = false;
				pressed = false;
				repaint();
			}

			@Override
			public void mousePressed(MouseEvent e)
			{
				pressed = true;
				repaint();
			}

			@Override
			public void mouseReleased(MouseEvent e)
			{
				boolean fire = pressed && contains(e.getPoint());
				pressed = false;
				repaint();
				if (fire)
				{
					action.run();
				}
			}
		});
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		int dy = pressed ? 1 : 0;
		RoundRectangle2D shape = new RoundRectangle2D.Float(0.5f, 0.5f + dy, w - 1, h - 2, 8, 8);
		Color text;
		if (primary)
		{
			Color top = hover ? Theme.GOLD_BRIGHT : Theme.GOLD;
			g.setPaint(new GradientPaint(0, 0, top, 0, h, Theme.GOLD_DIM));
			g.fill(shape);
			text = Theme.INK_DEEP;
		}
		else
		{
			g.setColor(hover ? Theme.alpha(Theme.GOLD, 40) : Theme.alpha(Theme.GOLD, 14));
			g.fill(shape);
			text = hover ? Theme.GOLD_BRIGHT : Theme.GOLD;
		}
		g.setColor(Theme.alpha(Theme.GOLD, primary ? 220 : 140));
		g.draw(shape);
		g.setFont(getFont());
		FontMetrics fm = g.getFontMetrics();
		g.setColor(text);
		g.drawString(this.text, (w - fm.stringWidth(this.text)) / 2, (h + fm.getAscent()) / 2 - 2 + dy);
		g.dispose();
	}
}

package com.codex.autopilot.ui;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RadialGradientPaint;
import java.awt.RenderingHints;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Path2D;
import java.awt.image.BufferedImage;
import javax.swing.JComponent;

/**
 * The crest at the top of the panel: the Autopilot medallion, how many steps the account has
 * waiting in large gilt figures, and a line on the most pressing of them.
 */
public class Crest extends JComponent
{
	private static final int HEIGHT = 104;

	private final Animator count = new Animator(this);
	private String heading = "ON YOUR ACCOUNT";
	private String status = "Log in to read your account";
	private String shortStatus;
	private Color statusColor = Theme.TEXT_MUTED;
	private boolean known;
	private String one = "step";
	private String many = "steps";
	private Color figureTint = Theme.GOLD;

	public Crest()
	{
		setOpaque(false);
		setPreferredSize(new Dimension(10, HEIGHT));
		setMinimumSize(new Dimension(10, HEIGHT));
	}

	/**
	 * @param figure how many, or null when not known
	 * @param one the unit for one, such as "step"
	 * @param many the unit for several
	 * @param status the line under the figure
	 * @param shortStatus a shorter line for when the status does not fit, or null
	 */
	public void update(String heading, Integer figure, String one, String many, String status, String shortStatus, Color statusColor, Color tint)
	{
		this.heading = heading;
		this.status = status;
		this.shortStatus = shortStatus;
		this.statusColor = statusColor;
		this.known = figure != null;
		this.one = one;
		this.many = many;
		this.figureTint = tint;
		if (figure != null)
		{
			count.set(figure, count.get() > 0);
		}
		repaint();
	}

	/**
	 * Draws text at twice the size of the game's bold font by doubling every pixel, the way the
	 * game itself draws large numbers, so the figures stay crisp instead of being re-rasterised.
	 *
	 * @return the width drawn
	 */
	static int paintLarge(Graphics2D g, String text, int x, int y, Color tint)
	{
		Font font = Theme.title();
		FontMetrics fm = g.getFontMetrics(font);
		int w = Math.max(1, fm.stringWidth(text) + 1);
		int h = fm.getHeight() + 1;
		BufferedImage small = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
		Graphics2D sg = small.createGraphics();
		sg.setFont(font);
		sg.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
		int base = fm.getAscent();
		sg.setColor(Color.BLACK);
		sg.drawString(text, 1, base + 1);
		sg.setPaint(new GradientPaint(0, base - fm.getAscent() + 3, Theme.mix(tint, Color.WHITE, 0.35), 0, base, tint));
		sg.drawString(text, 0, base);
		sg.dispose();
		Graphics2D lg = (Graphics2D) g.create();
		lg.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
		lg.drawImage(small, x, y - 2 * fm.getAscent() + 22, w * 2, h * 2, null);
		lg.dispose();
		return w * 2;
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		g.setPaint(new GradientPaint(0, 0, Theme.mix(Theme.INK, Theme.GOLD_DIM, 0.22), 0, h, Theme.INK));
		g.fillRect(0, 0, w, h);

		// The medallion: a gilt ring with the mark inside, lit from above.
		int mx = 10;
		int my = 14;
		int md = 54;
		g.setPaint(new RadialGradientPaint(mx + md / 2f, my + md / 3f, md * 0.7f, new float[]{0, 1},
			new Color[]{Theme.mix(Theme.CARD_TOP, Theme.GOLD_DIM, 0.35), Theme.INK_DEEP}));
		g.fill(new Ellipse2D.Float(mx, my, md, md));
		g.setStroke(new BasicStroke(2f));
		g.setPaint(new GradientPaint(mx, my, Theme.GOLD_BRIGHT, mx, my + md, Theme.GOLD_DIM));
		g.draw(new Ellipse2D.Float(mx + 1, my + 1, md - 2, md - 2));
		g.setStroke(new BasicStroke(1f));
		g.setColor(Theme.alpha(Theme.GOLD, 70));
		g.draw(new Ellipse2D.Float(mx + 5, my + 5, md - 10, md - 10));
		Sigil.paint(g, mx + 11, my + 11, md - 22);

		int tx = mx + md + 12;
		int room = w - tx - 8;
		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		g.setColor(Theme.TEXT_MUTED);
		g.drawString(Ui.clip(heading, small, room), tx, 22);

		String figure = !known ? "-" : String.valueOf(Math.round(count.get()));
		int top = 27;
		int figureW = paintLarge(g, figure, tx, top, known ? figureTint : Theme.GOLD_DIM);
		if (known)
		{
			g.setFont(Theme.small());
			g.setColor(Theme.GOLD_DIM);
			g.drawString(Math.round(count.get()) == 1 ? one : many, tx + figureW + 3, top + 18);
		}
		int cy = top + 50;
		g.setFont(Theme.small());
		if (status != null)
		{
			String line = shortStatus != null && small.stringWidth(status) > room ? shortStatus : status;
			Ui.shadowed(g, Ui.clip(line, small, room), tx, cy, statusColor);
		}

		// The gilt rule under the crest, with a diamond at its middle.
		int y = h - 2;
		g.setPaint(new GradientPaint(0, 0, Theme.alpha(Theme.GOLD, 0), w / 2f, 0, Theme.alpha(Theme.GOLD, 150), true));
		g.drawLine(0, y, w, y);
		Path2D diamond = new Path2D.Float();
		diamond.moveTo(w / 2f, y - 3);
		diamond.lineTo(w / 2f + 3, y);
		diamond.lineTo(w / 2f, y + 3);
		diamond.lineTo(w / 2f - 3, y);
		diamond.closePath();
		g.setColor(Theme.GOLD);
		g.fill(diamond);
		g.dispose();
	}
}

package com.codex.autopilot.ui;

import com.codex.autopilot.core.Candidate;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.Shape;
import java.awt.geom.Area;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Line2D;
import java.awt.geom.Path2D;
import java.awt.geom.Rectangle2D;
import java.awt.geom.RoundRectangle2D;

/**
 * A small engraved mark for each kind of step: a bird house, a tree, a sprout, a herb sprig, a hop
 * cone, an hourglass, a scroll, a crown, a star and a flag. Drawn rather than taken from item sprites, so it reads the
 * same at any size and in the game view.
 */
public final class Glyph
{
	private Glyph()
	{
	}

	/** Draws the mark for a kind in a size by size box, tinted. */
	public static void paint(Graphics2D g, Candidate.Kind kind, float x, float y, float size, Color tint)
	{
		Graphics2D gg = (Graphics2D) g.create();
		Theme.smooth(gg);
		gg.translate(x, y);
		gg.scale(size / 16f, size / 16f);
		Shape shape = shape(kind);
		Color light = Theme.mix(tint, Color.WHITE, 0.3);
		Color dark = Theme.mix(tint, Theme.INK_DEEP, 0.35);
		gg.setPaint(new GradientPaint(0, 1, light, 0, 15, dark));
		gg.fill(shape);
		gg.setStroke(new BasicStroke(0.9f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		gg.setColor(Theme.alpha(Theme.INK_DEEP, 230));
		gg.draw(shape);
		detail(gg, kind, tint);
		gg.dispose();
	}

	private static Shape shape(Candidate.Kind kind)
	{
		switch (kind)
		{
			case BIRDHOUSE_RUN:
			{
				Path2D p = new Path2D.Float();
				p.moveTo(8, 1.5);
				p.lineTo(14.5, 7);
				p.lineTo(12.6, 7);
				p.lineTo(12.6, 14.5);
				p.lineTo(3.4, 14.5);
				p.lineTo(3.4, 7);
				p.lineTo(1.5, 7);
				p.closePath();
				Area a = new Area(p);
				a.subtract(new Area(new Ellipse2D.Float(6.1f, 7.6f, 3.8f, 3.8f)));
				return a;
			}
			case TREE_RUN:
			{
				Area a = new Area(new Ellipse2D.Float(2.5f, 1.5f, 11, 9.5f));
				a.add(new Area(new Ellipse2D.Float(1.2f, 5f, 6.5f, 6f)));
				a.add(new Area(new Ellipse2D.Float(8.3f, 5f, 6.5f, 6f)));
				a.add(new Area(new Rectangle2D.Float(6.9f, 9.5f, 2.2f, 5.5f)));
				return a;
			}
			case PATCH_RUN:
			{
				Area a = new Area(leaf(8, 9, -1));
				a.add(new Area(leaf(8, 7.5f, 1)));
				a.add(new Area(new Rectangle2D.Float(7.3f, 7f, 1.4f, 6f)));
				a.add(new Area(new Ellipse2D.Float(3.5f, 12.2f, 9, 3)));
				return a;
			}
			case HERB_RUN:
			{
				// A sprig: three leaves on a stem.
				Area a = new Area(new Rectangle2D.Float(7.4f, 6f, 1.2f, 9f));
				a.add(new Area(leaf(8, 7.5f, -1)));
				a.add(new Area(leaf(8, 7.5f, 1)));
				Path2D top = new Path2D.Float();
				top.moveTo(8, 7);
				top.quadTo(4.6, 3.6, 8, 0.8);
				top.quadTo(11.4, 3.6, 8, 7);
				top.closePath();
				a.add(new Area(top));
				a.add(new Area(leaf(8, 12.5f, -1)));
				return a;
			}
			case HOPS_RUN:
			{
				// A hop cone hanging from its bine.
				Area a = new Area(new Ellipse2D.Float(4f, 3.5f, 8f, 11.5f));
				a.add(new Area(new Rectangle2D.Float(7.4f, 0.8f, 1.2f, 3.5f)));
				a.add(new Area(leaf(8.6f, 3f, 1)));
				return a;
			}
			case DAILIES:
			{
				Path2D p = new Path2D.Float();
				p.moveTo(3.5, 1.5);
				p.lineTo(12.5, 1.5);
				p.lineTo(12.5, 3);
				p.curveTo(12.5, 6, 9, 7, 9, 8);
				p.curveTo(9, 9, 12.5, 10, 12.5, 13);
				p.lineTo(12.5, 14.5);
				p.lineTo(3.5, 14.5);
				p.lineTo(3.5, 13);
				p.curveTo(3.5, 10, 7, 9, 7, 8);
				p.curveTo(7, 7, 3.5, 6, 3.5, 3);
				p.closePath();
				return p;
			}
			case CONTRACT:
			{
				Area a = new Area(new RoundRectangle2D.Float(3.5f, 2, 9, 12, 2, 2));
				a.add(new Area(new Ellipse2D.Float(2, 1, 3.5f, 3.5f)));
				a.add(new Area(new Ellipse2D.Float(10.5f, 11.5f, 3.5f, 3.5f)));
				return a;
			}
			case KINGDOM:
			{
				Path2D p = new Path2D.Float();
				p.moveTo(1.5, 5);
				p.lineTo(5, 8.5);
				p.lineTo(8, 2.5);
				p.lineTo(11, 8.5);
				p.lineTo(14.5, 5);
				p.lineTo(13, 13);
				p.lineTo(3, 13);
				p.closePath();
				Area a = new Area(p);
				a.add(new Area(new RoundRectangle2D.Float(3, 12.2f, 10, 2.4f, 1, 1)));
				return a;
			}
			case FOCUS_GOAL:
				return star(8, 8.4f, 7, 2.9f, 5);
			default:
			{
				Area a = new Area(new Rectangle2D.Float(3, 1.5f, 1.6f, 13.5f));
				Path2D flag = new Path2D.Float();
				flag.moveTo(4.4, 2);
				flag.curveTo(7, 1, 9, 3.5, 13.5, 2.5);
				flag.lineTo(13.5, 8.5);
				flag.curveTo(9, 9.5, 7, 7, 4.4, 8);
				flag.closePath();
				a.add(new Area(flag));
				return a;
			}
		}
	}

	/** Inked details that a fill alone would lose. */
	private static void detail(Graphics2D g, Candidate.Kind kind, Color tint)
	{
		g.setStroke(new BasicStroke(0.8f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.setColor(Theme.alpha(Theme.INK_DEEP, 200));
		switch (kind)
		{
			case DAILIES:
				g.setColor(Theme.mix(Theme.GOLD_BRIGHT, tint, 0.3));
				Path2D sand = new Path2D.Float();
				sand.moveTo(5.5, 13.6);
				sand.lineTo(10.5, 13.6);
				sand.lineTo(8, 11);
				sand.closePath();
				g.fill(sand);
				break;
			case CONTRACT:
				g.draw(new Line2D.Float(5.5f, 6, 10.5f, 6));
				g.draw(new Line2D.Float(5.5f, 8.5f, 10.5f, 8.5f));
				g.draw(new Line2D.Float(5.5f, 11, 9, 11));
				break;
			case KINGDOM:
				g.setColor(Theme.mix(Theme.TEAL, Color.WHITE, 0.3));
				g.fill(new Ellipse2D.Float(7, 9.2f, 2, 2));
				break;
			case HOPS_RUN:
				// The overlapping bracts.
				Path2D bracts = new Path2D.Float();
				bracts.moveTo(5, 7.5);
				bracts.quadTo(8, 9.5, 11, 7.5);
				bracts.moveTo(4.6, 10.5);
				bracts.quadTo(8, 12.5, 11.4, 10.5);
				bracts.moveTo(6, 13.4);
				bracts.quadTo(8, 14.6, 10, 13.4);
				g.draw(bracts);
				break;
			default:
				break;
		}
	}

	private static Shape leaf(float bx, float by, int side)
	{
		float tipX = bx + side * 5.5f;
		float tipY = by - 4.5f;
		Path2D p = new Path2D.Float();
		p.moveTo(bx, by);
		p.quadTo(bx + side * 0.8f, tipY - 0.8f, tipX, tipY);
		p.quadTo(bx + side * 5f, by + 0.6f, bx, by);
		p.closePath();
		return p;
	}

	private static Shape star(float cx, float cy, float outer, float inner, int points)
	{
		Path2D p = new Path2D.Float();
		for (int i = 0; i < points * 2; i++)
		{
			double a = Math.PI * i / points - Math.PI / 2;
			float r = i % 2 == 0 ? outer : inner;
			float px = (float) (cx + Math.cos(a) * r);
			float py = (float) (cy + Math.sin(a) * r);
			if (i == 0)
			{
				p.moveTo(px, py);
			}
			else
			{
				p.lineTo(px, py);
			}
		}
		p.closePath();
		return p;
	}
}

package com.codex.autopilot.ui;

import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.Path2D;
import javax.swing.JComponent;

/** A small-caps heading with a gold diamond and a line that fades into the dark. */
public class SectionHeader extends JComponent
{
	private final String text;
	private final String trailing;

	public SectionHeader(String text)
	{
		this(text, null);
	}

	public SectionHeader(String text, String trailing)
	{
		this.text = text.toUpperCase();
		this.trailing = trailing;
		setFont(Theme.small());
		setPreferredSize(new Dimension(10, 20));
		setMinimumSize(new Dimension(10, 20));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, 20));
		setAlignmentX(LEFT_ALIGNMENT);
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		g.setFont(getFont());
		paint(g, text, trailing, 0, 0, getWidth(), getHeight());
		g.dispose();
	}

	/** Draws a heading in a box; the card uses the same drawing. The font must already be set. */
	static void paint(Graphics2D g, String text, String trailing, int x, int y, int w, int h)
	{
		int mid = y + h / 2 + 2;
		Path2D diamond = new Path2D.Float();
		diamond.moveTo(x + 4, mid - 4);
		diamond.lineTo(x + 8, mid);
		diamond.lineTo(x + 4, mid + 4);
		diamond.lineTo(x, mid);
		diamond.closePath();
		g.setColor(Theme.GOLD);
		g.fill(diamond);

		FontMetrics fm = g.getFontMetrics();
		int textX = x + 13;
		int baseline = mid + fm.getAscent() / 2 - 1;
		g.setColor(Theme.GOLD);
		g.drawString(text, textX, baseline);

		int lineStart = textX + fm.stringWidth(text) + 6;
		int lineEnd = x + w;
		if (trailing != null && !trailing.isEmpty())
		{
			int tw = fm.stringWidth(trailing);
			lineEnd = x + w - tw - 6;
			g.setColor(Theme.TEXT_FAINT);
			g.drawString(trailing, x + w - tw, baseline);
		}
		if (lineEnd > lineStart)
		{
			g.setPaint(new GradientPaint(lineStart, 0, Theme.alpha(Theme.GOLD, 110), lineEnd, 0, Theme.alpha(Theme.GOLD, 0)));
			g.drawLine(lineStart, mid, lineEnd, mid);
		}
	}
}

package com.codex.autopilot.ui;

import java.awt.BasicStroke;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.RadialGradientPaint;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Line2D;
import java.awt.geom.Path2D;
import java.awt.image.BufferedImage;

/**
 * The Autopilot mark: a compass needle inside a gilt ring, its lit half pointing on to the next
 * step, with a teal pin at its heart.
 */
public final class Sigil
{
	/** Where the needle points: a little east of north, onward. */
	private static final double HEADING = Math.toRadians(38);

	private Sigil()
	{
	}

	public static BufferedImage icon(int size)
	{
		BufferedImage image = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		Theme.smooth(g);
		paint(g, 0, 0, size);
		g.dispose();
		return image;
	}

	/** Draws the mark in a size by size box. */
	public static void paint(Graphics2D g, float x, float y, float size)
	{
		float s = size / 16f;
		float cx = x + 8 * s;
		float cy = y + 8 * s;
		float r = 6.6f * s;

		// The ring: dark under, gilt over, with the four quarters marked.
		g.setStroke(new BasicStroke(Math.max(2.2f, 2.4f * s)));
		g.setColor(Theme.INK_DEEP);
		g.draw(new Ellipse2D.Float(cx - r, cy - r, r * 2, r * 2));
		g.setStroke(new BasicStroke(Math.max(1.1f, 1.2f * s)));
		g.setPaint(new GradientPaint(x, y, Theme.GOLD_BRIGHT, x, y + size, Theme.GOLD_DIM));
		g.draw(new Ellipse2D.Float(cx - r, cy - r, r * 2, r * 2));
		g.setStroke(new BasicStroke(Math.max(0.8f, 0.8f * s), BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		for (int i = 0; i < 4; i++)
		{
			double a = i * Math.PI / 2;
			float ox = (float) Math.sin(a);
			float oy = (float) -Math.cos(a);
			g.setColor(Theme.alpha(Theme.GOLD, 200));
			g.draw(new Line2D.Float(cx + ox * (r - 2.0f * s), cy + oy * (r - 2.0f * s), cx + ox * (r - 0.9f * s), cy + oy * (r - 0.9f * s)));
		}

		// The needle: a slim diamond, its forward half lit gold and its back half in shadow.
		float len = 5.6f * s;
		float half = 1.7f * s;
		float dx = (float) Math.sin(HEADING);
		float dy = (float) -Math.cos(HEADING);
		float nx = -dy;
		float ny = dx;
		Path2D front = new Path2D.Float();
		front.moveTo(cx + dx * len, cy + dy * len);
		front.lineTo(cx + nx * half, cy + ny * half);
		front.lineTo(cx - nx * half, cy - ny * half);
		front.closePath();
		Path2D back = new Path2D.Float();
		back.moveTo(cx - dx * len * 0.82f, cy - dy * len * 0.82f);
		back.lineTo(cx + nx * half, cy + ny * half);
		back.lineTo(cx - nx * half, cy - ny * half);
		back.closePath();
		g.setPaint(new GradientPaint(cx + dx * len, cy + dy * len, Theme.mix(Theme.GOLD_BRIGHT, java.awt.Color.WHITE, 0.25), cx, cy, Theme.GOLD));
		g.fill(front);
		g.setPaint(new GradientPaint(cx, cy, Theme.GOLD_DIM, cx - dx * len, cy - dy * len, Theme.mix(Theme.GOLD_DIM, Theme.INK_DEEP, 0.5)));
		g.fill(back);
		g.setStroke(new BasicStroke(Math.max(0.5f, 0.45f * s), BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.setColor(Theme.alpha(Theme.INK_DEEP, 220));
		g.draw(front);
		g.draw(back);

		// The pin: a teal stone, lit from above.
		float pr = Math.max(1.0f, 1.15f * s);
		g.setPaint(new RadialGradientPaint(cx - pr * 0.3f, cy - pr * 0.4f, pr * 1.6f, new float[]{0, 1},
			new java.awt.Color[]{Theme.mix(Theme.TEAL, java.awt.Color.WHITE, 0.45), Theme.mix(Theme.TEAL, Theme.INK_DEEP, 0.35)}));
		g.fill(new Ellipse2D.Float(cx - pr, cy - pr, pr * 2, pr * 2));
		g.setColor(Theme.INK_DEEP);
		g.setStroke(new BasicStroke(Math.max(0.4f, 0.35f * s)));
		g.draw(new Ellipse2D.Float(cx - pr, cy - pr, pr * 2, pr * 2));
	}
}

package com.codex.autopilot.ui;

import java.awt.Component;
import java.awt.Container;
import java.awt.Dimension;
import java.awt.Insets;
import java.awt.LayoutManager;
import java.awt.Rectangle;
import javax.swing.JPanel;
import javax.swing.Scrollable;
import javax.swing.border.EmptyBorder;

/**
 * A vertical stack where every child spans the full width at its preferred height.
 * It tracks the viewport width so nothing ever scrolls sideways in the side panel.
 */
public class StackPanel extends JPanel implements Scrollable
{
	public StackPanel(int gap, int pad)
	{
		super(new StackLayout(gap));
		setOpaque(false);
		setBorder(new EmptyBorder(pad, pad, pad, pad));
	}

	public StackPanel space(int height)
	{
		JPanel spacer = new JPanel();
		spacer.setOpaque(false);
		spacer.setPreferredSize(new Dimension(1, height));
		add(spacer);
		return this;
	}

	@Override
	public Dimension getPreferredScrollableViewportSize()
	{
		return getPreferredSize();
	}

	@Override
	public int getScrollableUnitIncrement(Rectangle visibleRect, int orientation, int direction)
	{
		return 16;
	}

	@Override
	public int getScrollableBlockIncrement(Rectangle visibleRect, int orientation, int direction)
	{
		return Math.max(16, visibleRect.height - 32);
	}

	@Override
	public boolean getScrollableTracksViewportWidth()
	{
		return true;
	}

	@Override
	public boolean getScrollableTracksViewportHeight()
	{
		return false;
	}

	static final class StackLayout implements LayoutManager
	{
		private final int gap;

		StackLayout(int gap)
		{
			this.gap = gap;
		}

		@Override
		public void addLayoutComponent(String name, Component comp)
		{
		}

		@Override
		public void removeLayoutComponent(Component comp)
		{
		}

		@Override
		public Dimension preferredLayoutSize(Container parent)
		{
			Insets in = parent.getInsets();
			int width = 0;
			int height = 0;
			int visible = 0;
			for (Component c : parent.getComponents())
			{
				if (!c.isVisible())
				{
					continue;
				}
				Dimension d = c.getPreferredSize();
				width = Math.max(width, d.width);
				height += d.height;
				visible++;
			}
			height += Math.max(0, visible - 1) * gap;
			return new Dimension(width + in.left + in.right, height + in.top + in.bottom);
		}

		@Override
		public Dimension minimumLayoutSize(Container parent)
		{
			return preferredLayoutSize(parent);
		}

		@Override
		public void layoutContainer(Container parent)
		{
			Insets in = parent.getInsets();
			int width = parent.getWidth() - in.left - in.right;
			int y = in.top;
			for (Component c : parent.getComponents())
			{
				if (!c.isVisible())
				{
					continue;
				}
				int h = c.getPreferredSize().height;
				c.setBounds(in.left, y, width, h);
				y += h + gap;
			}
		}
	}
}

package com.codex.autopilot.ui;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.Ellipse2D;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JComponent;

/** A small engraved tile: a quiet label over a value, with a lamp that is lit when the source is. */
public class StatTile extends JComponent
{
	static final int HEIGHT = 38;

	private final String label;
	private final String value;
	private final boolean live;

	public StatTile(String label, String value, boolean live)
	{
		this.label = label;
		this.value = value;
		this.live = live;
		setOpaque(false);
		setPreferredSize(new Dimension(10, HEIGHT));
		setToolTipText(label + ": " + value);
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		RoundRectangle2D shape = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1, h - 1, 8, 8);
		g.setPaint(new GradientPaint(0, 0, Theme.mix(Theme.INK_DEEP, Theme.CARD, 0.55), 0, h, Theme.INK_DEEP));
		g.fill(shape);
		g.setColor(Theme.STROKE_SOFT);
		g.draw(shape);

		Color lamp = live ? Theme.GREEN : Theme.TEXT_FAINT;
		if (live)
		{
			g.setColor(Theme.alpha(lamp, 60));
			g.fill(new Ellipse2D.Float(w - 13, 5, 8, 8));
		}
		g.setColor(lamp);
		g.fill(new Ellipse2D.Float(w - 11, 7, 4, 4));

		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		Ui.shadowed(g, Ui.clip(label.toUpperCase(), small, w - 22), 7, 14, Theme.TEXT_FAINT);
		g.setFont(Theme.body());
		FontMetrics body = g.getFontMetrics();
		Ui.shadowed(g, Ui.clip(value, body, w - 12), 7, 30, live ? Theme.TEXT : Theme.TEXT_MUTED);
		g.dispose();
	}
}

package com.codex.autopilot.ui;

import com.codex.autopilot.core.Bring;
import com.codex.autopilot.core.Candidate;
import java.awt.BasicStroke;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RadialGradientPaint;
import java.awt.geom.Ellipse2D;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JComponent;
import javax.swing.JPanel;

/**
 * A step on the panel. The lead step is large: its mark in a gilt medallion, the tier it sits in,
 * the step in gold, the why, what to bring and the two buttons. The steps after it are compact
 * rows with their place in the order.
 */
public final class StepCard
{
	private StepCard()
	{
	}

	/** The one best thing to do now. */
	public static Card lead(Candidate c, Actions actions, int width, boolean dim)
	{
		Color tint = dim ? Theme.TEXT_MUTED : Theme.tier(c.getTier());
		Card card = new Card(new BorderLayout(0, 6)).accent(tint).highlighted(!dim);
		card.add(new LeadHead(c, tint), BorderLayout.NORTH);

		StackPanel body = new StackPanel(3, 0);
		body.add(Ui.wrapped(c.getTitle(), Theme.title(), dim ? Theme.TEXT : Theme.GOLD_BRIGHT, width));
		body.add(Ui.wrapped(c.getWhy(), Theme.small(), Theme.TEXT, width));
		if (c.getBring() != null)
		{
			body.add(Ui.wrapped(c.getBring(), Theme.small(), Bring.isShort(c.getBring()) ? Theme.EMBER : Theme.TEAL, width));
		}
		card.add(body, BorderLayout.CENTER);
		if (actions != null)
		{
			card.add(buttons(c, actions, 22, FlowLayout.LEFT), BorderLayout.SOUTH);
		}
		return card;
	}

	/** A later step, numbered by its place. */
	public static Card row(int place, Candidate c, Actions actions, int width)
	{
		Color tint = Theme.tier(c.getTier());
		Card card = new Card(new BorderLayout(0, 3)).accent(tint);
		card.setBorder(new javax.swing.border.EmptyBorder(6, 10, 6, 8));
		card.add(new RowHead(place, c, tint), BorderLayout.NORTH);
		StackPanel body = new StackPanel(2, 0);
		body.add(Ui.wrapped(c.getTitle(), Theme.body(), Theme.TEXT, width));
		body.add(Ui.wrapped(c.getWhy(), Theme.small(), Theme.TEXT_MUTED, width));
		if (c.getBring() != null)
		{
			body.add(Ui.wrapped(c.getBring(), Theme.small(), Bring.isShort(c.getBring()) ? Theme.EMBER : Theme.alpha(Theme.TEAL, 220), width));
		}
		card.add(body, BorderLayout.CENTER);
		if (actions != null)
		{
			card.add(buttons(c, actions, 18, FlowLayout.RIGHT), BorderLayout.SOUTH);
		}
		return card;
	}

	private static JPanel buttons(Candidate c, Actions actions, int height, int align)
	{
		JPanel bar = new JPanel(new FlowLayout(align, 0, 0));
		bar.setOpaque(false);
		bar.add(new CodexButton("Skip", false, height, () -> actions.skip(c.getKey())));
		JPanel gap = new JPanel();
		gap.setOpaque(false);
		gap.setPreferredSize(new Dimension(5, height));
		bar.add(gap);
		bar.add(new CodexButton("Snooze 1h", false, height, () -> actions.snooze(c.getKey())));
		return bar;
	}

	/** "~11 min", or "1 hr" for the long ones. */
	public static String minutes(Candidate c)
	{
		int m = c.getMinutes();
		return m >= 60 ? "~1 hr" : "~" + m + " min";
	}

	/** "your pace" when the time was learned from the player's runs, "estimate" for a chore not yet learned, else null. */
	public static String paceNote(Candidate c)
	{
		if (c.isPaced())
		{
			return "your pace";
		}
		return c.getKind().isChore() ? "estimate" : null;
	}

	/** The lead step's head: the mark in its medallion, what kind of step, its tier and how long. */
	static final class LeadHead extends JComponent
	{
		private static final int HEIGHT = 34;
		private final Candidate c;
		private final Color tint;

		LeadHead(Candidate c, Color tint)
		{
			this.c = c;
			this.tint = tint;
			setOpaque(false);
			setPreferredSize(new Dimension(10, HEIGHT));
		}

		@Override
		protected void paintComponent(Graphics graphics)
		{
			Graphics2D g = (Graphics2D) graphics.create();
			Theme.smooth(g);
			int w = getWidth();
			int d = 32;
			int my = 1;
			g.setPaint(new RadialGradientPaint(d / 2f, my + d / 3f, d * 0.75f, new float[]{0, 1},
				new Color[]{Theme.mix(Theme.CARD_TOP, tint, 0.22), Theme.INK_DEEP}));
			g.fill(new Ellipse2D.Float(0, my, d, d));
			g.setStroke(new BasicStroke(1.4f));
			g.setPaint(new GradientPaint(0, my, Theme.mix(tint, Color.WHITE, 0.25), 0, my + d, Theme.mix(tint, Theme.INK_DEEP, 0.4)));
			g.draw(new Ellipse2D.Float(0.7f, my + 0.7f, d - 1.4f, d - 1.4f));
			g.setStroke(new BasicStroke(1f));
			Glyph.paint(g, c.getKind(), 8, my + 8, 16, tint);

			int tx = d + 8;
			g.setFont(Theme.small());
			FontMetrics small = g.getFontMetrics();
			String time = minutes(c);
			int pillW = small.stringWidth(time) + 12;
			int px = w - pillW;
			RoundRectangle2D pill = new RoundRectangle2D.Float(px + 0.5f, 3.5f, pillW - 1, 15, 8, 8);
			g.setColor(Theme.alpha(Theme.GOLD, 26));
			g.fill(pill);
			g.setColor(Theme.alpha(Theme.GOLD, 120));
			g.draw(pill);
			Ui.shadowed(g, time, px + 6, 15, Theme.GOLD);

			int room = px - tx - 6;
			Ui.shadowed(g, Ui.clip(c.getOver().toUpperCase(), small, room), tx, 14, Theme.GOLD);
			String note = paceNote(c);
			int noteW = 0;
			if (note != null)
			{
				noteW = small.stringWidth(note);
				Ui.shadowed(g, note, w - noteW - 1, 29, c.isPaced() ? Theme.TEAL : Theme.TEXT_FAINT);
			}
			Ui.shadowed(g, Ui.clip(c.getTier().getLabel(), small, w - tx - (noteW > 0 ? noteW + 6 : 0)), tx, 29, tint);
			g.dispose();
		}
	}

	/** A row's head: its place in a gilt ring, what kind of step and how long. */
	static final class RowHead extends JComponent
	{
		private static final int HEIGHT = 18;
		private final int place;
		private final Candidate c;
		private final Color tint;

		RowHead(int place, Candidate c, Color tint)
		{
			this.place = place;
			this.c = c;
			this.tint = tint;
			setOpaque(false);
			setPreferredSize(new Dimension(10, HEIGHT));
		}

		@Override
		protected void paintComponent(Graphics graphics)
		{
			Graphics2D g = (Graphics2D) graphics.create();
			Theme.smooth(g);
			int w = getWidth();
			g.setFont(Theme.small());
			FontMetrics small = g.getFontMetrics();

			g.setColor(Theme.INK_DEEP);
			g.fill(new Ellipse2D.Float(0, 1, 15, 15));
			g.setColor(Theme.alpha(tint, 190));
			g.draw(new Ellipse2D.Float(0.5f, 1.5f, 14, 14));
			String n = String.valueOf(place);
			Ui.shadowed(g, n, 8 - small.stringWidth(n) / 2, 13, Theme.GOLD_BRIGHT);

			Glyph.paint(g, c.getKind(), 20, 2, 13, tint);

			String time = minutes(c);
			int tw = small.stringWidth(time);
			// Teal when the time is the player's own pace.
			Ui.shadowed(g, time, w - tw, 13, c.isPaced() ? Theme.alpha(Theme.TEAL, 220) : Theme.TEXT_FAINT);
			Ui.shadowed(g, Ui.clip(c.getOver().toUpperCase(), small, w - 38 - tw - 6), 38, 13, Theme.GOLD_DIM);
			g.dispose();
		}
	}
}

package com.codex.autopilot.ui;

import com.codex.autopilot.core.Tier;
import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import net.runelite.client.ui.FontManager;

/**
 * The Codex look: warm ink, aged gold and a single arcane teal, drawn with the
 * game's own fonts so the panel reads as part of Gielinor rather than a web page.
 * Autopilot colours a step by how much it matters now: ember when something is about to go
 * to waste, green when a chore is ready, teal for the focused goal and gold for other goals.
 */
public final class Theme
{
	public static final Color INK = new Color(23, 20, 16);
	public static final Color INK_DEEP = new Color(16, 14, 11);
	public static final Color CARD = new Color(34, 30, 24);
	public static final Color CARD_TOP = new Color(42, 37, 29);
	public static final Color CARD_HOVER = new Color(48, 42, 33);
	public static final Color STROKE = new Color(66, 56, 42);
	public static final Color STROKE_SOFT = new Color(48, 41, 32);

	public static final Color GOLD = new Color(214, 178, 106);
	public static final Color GOLD_BRIGHT = new Color(246, 214, 144);
	public static final Color GOLD_DIM = new Color(132, 108, 66);
	public static final Color TEAL = new Color(96, 184, 170);
	public static final Color GREEN = new Color(130, 196, 108);
	public static final Color EMBER = new Color(222, 134, 86);
	public static final Color BLOCKED = new Color(176, 92, 84);
	public static final Color BLOOD = new Color(204, 70, 60);
	public static final Color BLOOD_DEEP = new Color(120, 32, 28);
	public static final Color VIOLET = new Color(176, 132, 222);

	public static final Color TEXT = new Color(234, 224, 202);
	public static final Color TEXT_MUTED = new Color(160, 148, 126);
	public static final Color TEXT_FAINT = new Color(110, 100, 84);

	public static final int RADIUS = 10;
	public static final int GUTTER = 8;

	private Theme()
	{
	}

	public static Font title()
	{
		return FontManager.getRunescapeBoldFont();
	}

	public static Font body()
	{
		return FontManager.getRunescapeFont();
	}

	public static Font small()
	{
		return FontManager.getRunescapeSmallFont();
	}

	public static Color alpha(Color c, int alpha)
	{
		return new Color(c.getRed(), c.getGreen(), c.getBlue(), alpha);
	}

	public static Color mix(Color a, Color b, double t)
	{
		t = Math.max(0, Math.min(1, t));
		return new Color(
			(int) Math.round(a.getRed() + (b.getRed() - a.getRed()) * t),
			(int) Math.round(a.getGreen() + (b.getGreen() - a.getGreen()) * t),
			(int) Math.round(a.getBlue() + (b.getBlue() - a.getBlue()) * t),
			(int) Math.round(a.getAlpha() + (b.getAlpha() - a.getAlpha()) * t));
	}

	/** Progress colour: ember when just begun, gold through the middle, green when nearly there. */
	public static Color progressColor(double progress)
	{
		if (progress >= 1)
		{
			return GREEN;
		}
		if (progress < 0.5)
		{
			return mix(EMBER, GOLD, progress * 2);
		}
		return mix(GOLD, TEAL, (progress - 0.5) * 2);
	}

	/** The colour of a step's tier. */
	public static Color tier(Tier tier)
	{
		switch (tier)
		{
			case WASTING:
				return EMBER;
			case READY:
				return GREEN;
			case FOCUS:
				return TEAL;
			default:
				return GOLD;
		}
	}

	/** Smooth shapes, but the pixel fonts stay crisp. */
	public static void smooth(Graphics2D g)
	{
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
		g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
	}
}

package com.codex.autopilot.ui;

import java.awt.Color;
import java.awt.Component;
import java.awt.Container;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.event.MouseAdapter;
import javax.swing.JLabel;

/** Small helpers shared by the panel's components. */
public final class Ui
{
	private Ui()
	{
	}

	public static JLabel label(String text, Font font, Color color)
	{
		JLabel label = new JLabel(text);
		label.setFont(font);
		label.setForeground(color);
		return label;
	}

	/**
	 * A label that wraps inside the side panel's narrow width. Swing's HTML renderer
	 * treats CSS pixels as points, so the width is converted to keep it in screen pixels.
	 */
	public static JLabel wrapped(String text, Font font, Color color, int width)
	{
		int css = Math.round(width * 0.75f);
		return label("<html><div style='width:" + css + "px'>" + escape(text) + "</div></html>", font, color);
	}

	public static String escape(String text)
	{
		return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	/** Lets a clickable card keep its hover and click while the pointer is over its children. */
	static void forwardMouse(Container root, MouseAdapter adapter)
	{
		for (Component child : root.getComponents())
		{
			child.addMouseListener(adapter);
			if (child instanceof Container)
			{
				forwardMouse((Container) child, adapter);
			}
		}
	}

	/** Text with the one pixel black shadow the game puts under its own lettering. */
	public static void shadowed(Graphics2D g, String text, int x, int y, Color color)
	{
		g.setColor(Color.BLACK);
		g.drawString(text, x + 1, y + 1);
		g.setColor(color);
		g.drawString(text, x, y);
	}

	/** Cuts text to fit a width, ending it with an ellipsis. */
	public static String clip(String text, java.awt.FontMetrics fm, int width)
	{
		if (text == null)
		{
			return "";
		}
		if (fm.stringWidth(text) <= width)
		{
			return text;
		}
		int end = text.length();
		while (end > 0 && fm.stringWidth(text.substring(0, end) + "...") > width)
		{
			end--;
		}
		return text.substring(0, end) + "...";
	}
}

package com.codex.autopilot.ui;

import com.codex.autopilot.core.Activity;
import com.codex.autopilot.core.Budget;
import com.codex.autopilot.core.Plan;
import java.util.Collections;
import java.util.List;

/** Everything the panel shows, built off the Swing thread and handed over whole. */
public final class View
{
	/** One source Autopilot reads, for the tiles at the foot of the panel. */
	public static final class Source
	{
		public final String label;
		public final String value;
		/** True when the source was read and gave something. */
		public final boolean live;

		public Source(String label, String value, boolean live)
		{
			this.label = label;
			this.value = value;
			this.live = live;
		}
	}

	public final boolean loggedIn;
	/** Whether there is an account profile to read at all. */
	public final boolean known;
	public final Plan plan;
	public final Activity activity;
	/** True when Codex Minigame Pilot is switched on, so it can be named as the one guiding. */
	public final boolean minigamePilot;
	/** What comes ready next when nothing is due, such as "Bird houses full in 23 min", or null. */
	public final String nextUp;
	public final boolean quiet;
	public final boolean skipped;
	public final List<Source> sources;
	/** The time the player said they have. */
	public final Budget budget;
	/** What fits it; every step when there is no limit. */
	public final Budget.Fit fit;

	public View(boolean loggedIn, boolean known, Plan plan, Activity activity, boolean minigamePilot, String nextUp,
		boolean quiet, boolean skipped, List<Source> sources)
	{
		this(loggedIn, known, plan, activity, minigamePilot, nextUp, quiet, skipped, sources, Budget.NONE, null);
	}

	public View(boolean loggedIn, boolean known, Plan plan, Activity activity, boolean minigamePilot, String nextUp,
		boolean quiet, boolean skipped, List<Source> sources, Budget budget, Budget.Fit fit)
	{
		this.loggedIn = loggedIn;
		this.known = known;
		this.plan = plan == null ? Plan.EMPTY : plan;
		this.activity = activity == null ? Activity.NONE : activity;
		this.minigamePilot = minigamePilot;
		this.nextUp = nextUp;
		this.quiet = quiet;
		this.skipped = skipped;
		this.sources = sources == null ? Collections.emptyList() : sources;
		this.budget = budget == null ? Budget.NONE : budget;
		this.fit = fit == null ? Budget.Fit.NONE : fit;
	}

	/** Whether a time budget is set, so the panel shows what fits rather than everything. */
	public boolean budgeted()
	{
		return budget != Budget.NONE;
	}

	public static View empty()
	{
		return new View(false, false, Plan.EMPTY, Activity.NONE, false, null, false, false, null);
	}

	public boolean steppingAside()
	{
		return activity != Activity.NONE;
	}
}

package com.codex.autopilot.core;

